@app.before_request
def _portal_only():
    if os.environ.get("PORTAL_ONLY", "").lower() != "true":
        return
    p = request.path
    if p == "/portal" or p.startswith("/portal/") or p.startswith("/static/") or p == "/favicon.ico":
        return
    return Response("Forbidden", 403)

