def _norm_name(s):
    """Normalizuj nazwisko: usuń polskie znaki, małe litery, oczyść spacje."""
    s = (s or "").strip()
    nfkd = unicodedata.normalize('NFKD', s)
    ascii_s = ''.join(c for c in nfkd if not unicodedata.combining(c))
    ascii_s = ascii_s.lower()
    ascii_s = re.sub(r'[^a-z\s]', ' ', ascii_s)
    return re.sub(r'\s+', ' ', ascii_s).strip()

def _levenshtein(a, b):
    """Odległość Levenshteina między dwoma stringami."""
    if len(a) < len(b):
        return _levenshtein(b, a)
    if not b:
        return len(a)
    prev = list(range(len(b) + 1))
    for ca in a:
        curr = [prev[0] + 1]
        for j, cb in enumerate(b):
            curr.append(min(prev[j + 1] + 1, curr[j] + 1, prev[j] + (0 if ca == cb else 1)))
        prev = curr
    return prev[len(b)]

def _find_opp_player(db, raw_name, club_name=None):
    """Znajdź pasującego zawodnika w bazie. Zwraca (player_id, confidence_pct, method)."""
    norm = _norm_name(raw_name)
    if not norm:
        return None, 0, 'none'
    cur = db.cursor(cursor_factory=RealDictCursor)
    cur.execute("SELECT player_id FROM opp_aliases WHERE normalized = %s LIMIT 1", (norm,))
    row = cur.fetchone()
    if row:
        cur.close()
        return row['player_id'], 100, 'alias'
    q = "SELECT id, imie, nazwisko FROM opp_players"
    params = []
    if club_name:
        q += " WHERE LOWER(club_name) = LOWER(%s)"
        params.append(club_name)
    cur.execute(q, params)
    players = cur.fetchall()
    cur.close()
    best_id, best_score = None, 0
    for p in players:
        p_norm = _norm_name(f"{p['imie']} {p['nazwisko']}")
        max_len = max(len(norm), len(p_norm), 1)
        score = round((1 - _levenshtein(norm, p_norm) / max_len) * 100)
        if score > best_score:
            best_score, best_id = score, p['id']
    if best_score >= 85:
        return best_id, best_score, 'fuzzy'
    return None, best_score, 'none'

def _parse_fiba_image(image_b64, mime_type):
    """Wywołaj Claude Vision API do sparsowania arkusza FIBA. Zwraca (dict|None, error|None)."""
    api_key = os.environ.get("ANTHROPIC_API_KEY", "")
    if not api_key:
        return None, "Brak ANTHROPIC_API_KEY — ustaw zmienną środowiskową w docker-compose.yml"
    try:
        import anthropic as _ant
    except ImportError:
        return None, "Biblioteka anthropic nie jest zainstalowana (sprawdź Dockerfile)"
    client = _ant.Anthropic(api_key=api_key)
    prompt = """Przeanalizuj arkusz statystyk meczowych FIBA. Zwróć WYŁĄCZNIE poprawny JSON bez markdown.

{
  "zawody": "nazwa rozgrywek",
  "data": "YYYY-MM-DD lub pusty string",
  "team_a": "nazwa drużyny A (lewa kolumna / gospodarz)",
  "team_b": "nazwa drużyny B (prawa kolumna / gość)",
  "wynik_a": 0,
  "wynik_b": 0,
  "kwarty_a": [0,0,0,0],
  "kwarty_b": [0,0,0,0],
  "trener_a": "",
  "trener_b": "",
  "sedzia": "",
  "publicznosc": 0,
  "bench_pts_a": 0, "bench_pts_b": 0,
  "fast_break_a": 0, "fast_break_b": 0,
  "paint_pts_a": 0,  "paint_pts_b": 0,
  "biggest_lead_a": 0, "biggest_lead_b": 0,
  "time_in_lead_a": "",
  "lead_changes": 0,
  "players_a": [
    {"nr":0,"nazwisko_imie":"NAZWISKO Imie","min":"00:00","pts":0,
     "p2m":0,"p2a":0,"p3m":0,"p3a":0,"ftm":0,"fta":0,
     "oreb":0,"dreb":0,"ast":0,"stl":0,"blk":0,
     "bp":0,"fp":0,"fw":0,"plus_minus":0,"ef":0}
  ],
  "players_b": []
}

ZASADY:
- Przepisuj nazwiska DOKŁADNIE jak w arkuszu (polskie litery, skróty imion)
- Dla brakujących liczb użyj 0
- minutes: format MM:SS np. "17:43"
- data: YYYY-MM-DD lub pusty string gdy nieczytelna"""
    try:
        msg = client.messages.create(
            model="claude-haiku-4-5-20251001",
            max_tokens=4096,
            messages=[{"role": "user", "content": [
                {"type": "image", "source": {"type": "base64", "media_type": mime_type, "data": image_b64}},
                {"type": "text", "text": prompt}
            ]}]
        )
        text = msg.content[0].text.strip()
        text = re.sub(r'^```[a-z]*\n?', '', text)
        text = re.sub(r'\n?```$', '', text.rstrip())
        return json.loads(text), None
    except json.JSONDecodeError as e:
        return None, f"Błąd parsowania JSON z Claude: {e}"
    except Exception as e:
        return None, f"Błąd Claude API: {e}"

def _min_str_to_sec(s):
    """Zamień 'MM:SS' na sekundy całkowite."""
    try:
        parts = str(s or "").split(":")
        return int(parts[0]) * 60 + int(parts[1]) if len(parts) == 2 else 0
    except Exception:
        return 0


