def _js_dumps(obj):
    """JSON bezpieczny do wstawienia w <script> — zamyka próbę wyjścia z tagu."""
    import json as _jd
    return (_jd.dumps(obj, ensure_ascii=False)
            .replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026"))


