    def _mz_hc_strip(zlist, is_hot):
        if not zlist: return ""
        cols = ["#e03030","#e55050","#e88080"] if is_hot else ["#4a90d9","#6ba5e0","#8bbfed"]
        lbl = "TOP 3" if is_hot else "LOW 3"
