    _mz_tbl_atk = _build_mz_zone_tbl(_mz_atk, _MZ_ATK_NAMES, _MZ_ATK_PTS)
    _mz_tbl_def = _build_mz_zone_tbl(_mz_def, _MZ_DEF_NAMES, _MZ_DEF_PTS, is_def=True)

    _mz_tp_zones = []
