  #sDynamika table {{ font-size:12px !important; }}
  #sDynamika th, #sDynamika td {{ padding:3px 5px !important; }}
  #sDynamika [style*="background:linear-gradient"] {{ padding:8px 12px !important; }}
  #sDynamika [style*="font-size:42px"],
  #sDynamika [style*="font-size:38px"],
  #sDynamika [style*="font-size:36px"] {{ font-size:26px !important; }}
