@app.route("/raporty/mecz")
@login_required
def raporty_mecz_lista():
    """Lista meczów do wyboru dla raportu meczowego."""
    db = get_db(); cur = db.cursor()
    cur.execute("""
        SELECT id, data_meczu, przeciwnik, wynik_gtk, wynik_opp, sezon, rozgrywki,
               team_name_a
        FROM matches
        ORDER BY data_meczu DESC, id DESC
    """)
    mecze = list(cur.fetchall())
    cur.close()

    rows = ""
    for m in mecze:
        is_win = (m.get("wynik_gtk") or 0) > (m.get("wynik_opp") or 0)
        badge_c = "#1a6b3c" if is_win else "#8b1a1a"
        badge_l = "W" if is_win else "P"
        dt = m["data_meczu"].strftime("%d.%m.%Y") if m.get("data_meczu") else "—"
        rows += f"""<tr class="report-row" data-search="{(m.get('przeciwnik','') or '').lower()} {m.get('sezon','')} {m.get('rozgrywki','')}"
                    style="border-bottom:1px solid #f0f4f8">
          <td style="padding:8px 12px;font-size:.78rem;color:#888">{dt}</td>
          <td style="padding:8px 12px">
            <span style="display:inline-block;width:18px;height:18px;border-radius:4px;background:#e8ecf3;color:{badge_c};font-size:.65rem;font-weight:800;text-align:center;line-height:18px">{badge_l}</span>
            <a href="/raporty/mecz/{m['id']}" style="color:#1a2b4a;font-weight:600;text-decoration:none;margin-left:8px">vs {m.get('przeciwnik','?')}</a>
          </td>
          <td style="padding:8px 12px;text-align:center;font-size:.82rem;font-weight:700;color:{'#1a6b3c' if is_win else '#8b1a1a'}">{m.get('wynik_gtk',0)} : {m.get('wynik_opp',0)}</td>
          <td style="padding:8px 12px;font-size:.78rem;color:#888">{m.get('sezon','')}</td>
          <td style="padding:8px 12px;font-size:.78rem;color:#888">{m.get('rozgrywki','')}</td>
          <td style="padding:8px 12px;text-align:right">
            <a href="/raporty/mecz/{m['id']}" class="btn btn-sm" style="background:#1a2b4a;color:#fff;font-size:.72rem">📄 Raport</a>
          </td>
        </tr>"""

    content = f"""
<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px;flex-wrap:wrap">
  <a href="/raporty" class="btn btn-sm btn-outline-secondary">← Wstecz</a>
  <div class="page-title mb-0">🏀 Raport meczowy — wybierz mecz</div>
  <div style="margin-left:auto;display:flex;align-items:center;gap:6px;position:relative">
    <span style="position:absolute;left:10px;top:50%;transform:translateY(-50%);color:#9ca3af;pointer-events:none">🔍</span>
    <input type="text" placeholder="Szukaj meczu..." autocomplete="off"
           oninput="filterReportPlayers(this.value)"
           style="padding:6px 10px 6px 30px;border:1px solid #e8ecf3;border-radius:8px;font-size:.85rem;width:260px;outline:none">
  </div>
</div>
<div class="card" style="border:1px solid #e8ecf3">
  <div class="card-body" style="padding:0">
    <table style="width:100%;border-collapse:collapse">
      <thead>
        <tr style="background:#1a2b4a;color:#fff">
          <th style="padding:10px 12px;font-size:.7rem;font-weight:600;letter-spacing:.04em">Data</th>
          <th style="padding:10px 12px;font-size:.7rem;font-weight:600;letter-spacing:.04em">Mecz</th>
          <th style="padding:10px 12px;font-size:.7rem;text-align:center;font-weight:600;letter-spacing:.04em">Wynik</th>
          <th style="padding:10px 12px;font-size:.7rem;font-weight:600;letter-spacing:.04em">Sezon</th>
          <th style="padding:10px 12px;font-size:.7rem;font-weight:600;letter-spacing:.04em">Liga</th>
          <th style="padding:10px 12px;font-size:.7rem;text-align:right;font-weight:600;letter-spacing:.04em">Akcja</th>
        </tr>
      </thead>
      <tbody id="reportTbody">{rows or '<tr><td colspan="6" style="padding:30px;text-align:center;color:#aaa">Brak meczów</td></tr>'}</tbody>
      <tfoot><tr id="reportEmpty" style="display:none"><td colspan="6" style="padding:24px;text-align:center;color:#aaa;font-size:.85rem">Brak wyników</td></tr></tfoot>
    </table>
  </div>
</div>
<script>
function filterReportPlayers(q){{
  var query=(q||'').trim().toLowerCase();
  var rows=document.querySelectorAll('#reportTbody .report-row');
  var visible=0;
  rows.forEach(function(r){{
    var ok=!query||(r.getAttribute('data-search')||'').indexOf(query)!==-1;
    r.style.display=ok?'':'none';
    if(ok)visible++;
  }});
  var e=document.getElementById('reportEmpty');
  if(e)e.style.display=(visible===0&&query)?'':'none';
}}
</script>
"""
    return html_response(base(content, active="raporty"))


