    try:
        db = get_db(); cur = db.cursor()
        cur.execute("SELECT imie, nazwisko FROM persons WHERE id=%s", (person_id,))
        _p = cur.fetchone()
        cur.close()
        _name = f"{(_p.get('nazwisko') or '').strip()}_{(_p.get('imie') or '').strip()}".strip("_") if _p else f"id{person_id}"
    except Exception:
        _name = f"id{person_id}"
    safe = lambda s: (s or "").replace(" ", "_").replace("/", "-").replace("\\", "-")
    fn = f"raport-zawodnik-{safe(_name) or person_id}-{safe(sezon_filter) or 'kariera'}.pdf"
    return _render_view_as_pdf(
        view_func=raporty_zawodnik_szczegoly,
        internal_url=f"/raporty/zawodnik/{person_id}?sezon={sezon_filter}",
        filename=fn,
        view_args={"person_id": person_id},
        landscape=True,
    )


