@app.route("/druzyny/upload-logo", methods=["POST"])
@login_required
def druzyny_upload_logo():
    import base64 as _b64
    from flask import jsonify
    if "logo" not in request.files:
        return jsonify(ok=False, error="Brak pliku")
    f = request.files["logo"]
    if not f or not f.filename:
        return jsonify(ok=False, error="Brak pliku")
    ext = f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else ""
    if ext not in {"png", "jpg", "jpeg", "webp"}:
        return jsonify(ok=False, error="Dozwolone: PNG, JPG, WEBP")
    klub = request.form.get("klub", "").strip()
    if not klub:
        return jsonify(ok=False, error="Brak nazwy klubu")
    mime = {"png": "image/png", "jpg": "image/jpeg", "jpeg": "image/jpeg", "webp": "image/webp"}.get(ext, "image/png")
    data_uri = f"data:{mime};base64," + _b64.b64encode(f.read()).decode()
    safe_klub = klub.replace(" ", "_").replace("/", "-")
    set_setting(f"logo_{safe_klub}", data_uri)
    return jsonify(ok=True, logo=data_uri)


@app.route("/druzyny/js")
def druzyny_js():
    """Serve the druzyny JavaScript file"""
    from flask import Response
    import os as _os
    for _path in ('/app/static/druzyny.js', '/app/druzyny.js'):
        if _os.path.exists(_path):
            return Response(open(_path, encoding='utf-8').read(), mimetype='application/javascript')
    return Response(DRUZYNY_JS, mimetype='application/javascript')


