@app.route("/mecz/<int:match_id>/export/xlsx")
@login_required
def export_match_xlsx(match_id):
    db = get_db(); cur = db.cursor()
    cur.execute("SELECT * FROM matches WHERE id=%s", (match_id,))
    m = cur.fetchone()
    if not m: return redirect(url_for("historia"))

    gtk_name = (m.get("team_name_a","") or m.get("nazwa_gtk","") or "").strip() or get_team_short_name()
    name_opp = (m.get("team_name_b","") or m["przeciwnik"])
    dt = m['data_meczu'].strftime('%d.%m.%Y') if m['data_meczu'] else ""

    cur.execute("SELECT * FROM match_stats WHERE match_id=%s ORDER BY kwarta", (match_id,))
    all_stats = list(cur.fetchall())
    cur.execute("SELECT * FROM player_stats WHERE match_id=%s", (match_id,))
    all_players = list(cur.fetchall())
    cur.execute("SELECT * FROM timing_stats WHERE match_id=%s", (match_id,))
    all_timing = list(cur.fetchall())
    cur.close()

    # Wczytaj szablon (wbudowany w kod)
    import base64 as _b64
    tmpl = openpyxl.load_workbook(io.BytesIO(_b64.b64decode(_get_szablon_b64())))

    def qd(druzyna, kwarta):
        r = next((dict(x) for x in all_stats if x["druzyna"]==druzyna and x["kwarta"]==kwarta), {})
        return r

    def td(druzyna, bucket):
        r = next((dict(x) for x in all_timing if x["druzyna"]==druzyna and x["bucket"]==bucket), {})
        return r

    CTR = Alignment(horizontal="center", vertical="center")
    YEL = PatternFill("solid", fgColor="FFF9C4")

    def fill_cell(ws, row, col, val):
        c = ws.cell(row, col, val)
        c.alignment = CTR

    # ── TEAM GENERAL ─────────────────────────────────────────────────────────
    # Kolumny wg szablonu (wiersz 4):
    # A=drużyna/kwarta, B=FTA, C=FTM, D=FT miss, E=FT%,
    # F=2PM, G=2P miss, H=2PA, I=2P%, J=3PM, K=3P miss, L=3PA, M=3P%,
    # N=2+1, O=3+1, P=Tip made, Q=Tip miss, R=Tip sum, S=Tip%,
    # T=OREB, U=DREB, V=REB, W=AST, X=TO, Y=P, Z=FD,
    # AD=POSS, AG=PTS, AK=PPP, AM=eFG%, AN=TS%, AO=TO%, AP=FTr, AQ=ORtg
    ws1 = tmpl['TEAM GENERAL']
    ws1['A1'] = f"STATYSTYKI DRUŻYNOWE — {gtk_name} vs {name_opp} | {dt}"

    Q_NAMES = {1:"IQ", 2:"IIQ", 3:"IIIQ", 4:"IVQ"}

    for team_label, druzyna, start_row in [(gtk_name,"gtk",6),(name_opp,"opp",14)]:
        ws1.cell(start_row-1, 1, f"  ▶  {team_label}")
        for qi, qn in enumerate([1,2,3,4]):
            r = start_row + qi
            q = qd(druzyna, qn)
            ws1.cell(r,1, Q_NAMES[qn])
            fill_cell(ws1, r, 2, q.get("fta",0))    # FTA
            fill_cell(ws1, r, 3, q.get("ftm",0))    # FTM
            fill_cell(ws1, r, 6, q.get("p2m",0))    # 2PM
            fill_cell(ws1, r, 8, q.get("p2a",0))    # 2PA
            fill_cell(ws1, r, 7, q.get("p2a",0)-q.get("p2m",0))  # 2P miss
            fill_cell(ws1, r, 10, q.get("p3m",0))   # 3PM
            fill_cell(ws1, r, 12, q.get("p3a",0))   # 3PA
            fill_cell(ws1, r, 11, q.get("p3a",0)-q.get("p3m",0)) # 3P miss
            fill_cell(ws1, r, 24, q.get("br",0))    # TO/BR
            fill_cell(ws1, r, 26, q.get("fd",0))    # FD
            fill_cell(ws1, r, 30, q.get("poss",0))  # POSS
            fill_cell(ws1, r, 33, q.get("pts",0))   # PTS
        # OT row
        ws1.cell(start_row+4, 1, "OT")

    # ── PLAYERS ──────────────────────────────────────────────────────────────
    # Kolumny: A=Zawodnik, B=#, C=2PM, D=2PA, E=3PM, F=3PA, G=FTM, H=FTA,
    #          I=BLK, J=OREB, K=DREB, L=AST, M=TO, N=PF, O=STL, P=FD,
    #          Q=PTS, R=MIN, ...
    ws2 = tmpl['PLAYERS']
    start = 4
    for druzyna, label in [("gtk", gtk_name), ("opp", name_opp)]:
        ws2.cell(start, 1, f"  ▶  {label}")
        players = sorted([p for p in all_players if p["druzyna"]==druzyna],
                         key=lambda x: x["pts"], reverse=True)
        for i, p in enumerate(players):
            r = start + 1 + i
            fill_cell(ws2, r, 1, "")           # Zawodnik (brak nazwy w DB)
            fill_cell(ws2, r, 2, p["nr"])      # #
            fill_cell(ws2, r, 3, p["p2m"])     # 2PM
            fill_cell(ws2, r, 4, p["p2a"])     # 2PA
            fill_cell(ws2, r, 5, p["p3m"])     # 3PM
            fill_cell(ws2, r, 6, p["p3a"])     # 3PA
            fill_cell(ws2, r, 7, p["ftm"])     # FTM
            fill_cell(ws2, r, 8, p["fta"])     # FTA
            fill_cell(ws2, r, 10, p["oreb"])   # OREB
            fill_cell(ws2, r, 11, p["dreb"])   # DREB
            fill_cell(ws2, r, 12, p["ast"])    # AST
            fill_cell(ws2, r, 13, p["br"])     # TO
            fill_cell(ws2, r, 16, p["fd"])     # FD
            fill_cell(ws2, r, 17, p["pts"])    # PTS
        start = start + len(players) + 2
        if start < 20: start = 20  # separator między drużynami
        ws2.cell(start, 1, f"  ▶  {name_opp if druzyna=='gtk' else ''}")

    # ── SHOT TIMING ────────────────────────────────────────────────────────
    # Kolumny D-Q = celne/niecelne per bucket (0s,1-4s,5-8s,9-12s,13-16s,17-20s,21-24s)
    # Col D=Cel.0s, E=Niec.0s, F=Cel.1-4s, G=Niec.1-4s, ..., P=Cel.21-24s, Q=Niec.21-24s
    ws4 = tmpl['SHOT TIMING']
    bucket_cols = {
        "0s":    (4,5),
        "1-4s":  (6,7),
        "5-8s":  (8,9),
        "9-12s": (10,11),
        "13-16s":(12,13),
        "17-20s":(14,15),
        "21-24s":(16,17),
    }
    Q_LABEL = {1:"IQ", 2:"IIQ", 3:"IIIQ", 4:"IVQ"}

    # Mapowanie wierszy: TWOJA DRUŻYNA IQ 2PT=row4, IQ 3PT=row5, IQ ALL=row6, ...
    def timing_row(druzyna_label, kwarta_label, typ):
        base = 4 if druzyna_label == gtk_name else 22
        q_idx = {"IQ":0,"IIQ":1,"IIIQ":2,"IVQ":3,"OT":4,"SUMA":5}[kwarta_label]
        typ_idx = {"2PT":0,"3PT":1,"ALL":2}[typ]
        return base + q_idx*3 + typ_idx

    for druzyna, label in [("gtk", gtk_name), ("opp", name_opp)]:
        # Wpisz nazwy drużyn i kwart
        for qi, qn in enumerate([1,2,3,4]):
            for typ in ["2PT","3PT","ALL"]:
                r = timing_row(label, Q_LABEL[qn], typ)
                ws4.cell(r, 1, label)
                ws4.cell(r, 2, Q_LABEL[qn])
                ws4.cell(r, 3, typ)

            # Dane per bucket
            t2 = td(druzyna, "0s")  # placeholder
            for b, (col_made, col_miss) in bucket_cols.items():
                t = td(druzyna, b)
                q_timing_all = [x for x in all_timing
                                if x["druzyna"]==druzyna and x["bucket"]==b]
                # 2PT row
                r2 = timing_row(label, Q_LABEL[qn], "2PT")
                r3 = timing_row(label, Q_LABEL[qn], "3PT")

            # Suma per bucket (wszystkie kwarty)
            for b, (col_made, col_miss) in bucket_cols.items():
                t = td(druzyna, b)
                r_sum2 = timing_row(label, "SUMA", "2PT")
                r_sum3 = timing_row(label, "SUMA", "3PT")
                fill_cell(ws4, r_sum2, col_made, t.get("made2",0))
                fill_cell(ws4, r_sum2, col_miss, t.get("att2",0)-t.get("made2",0))
                fill_cell(ws4, r_sum3, col_made, t.get("made3",0))
                fill_cell(ws4, r_sum3, col_miss, t.get("att3",0)-t.get("made3",0))

    buf = io.BytesIO()
    tmpl.save(buf)
    buf.seek(0)
    filename = f"raport_{gtk_name}_vs_{name_opp}_{dt}.xlsx".replace(" ","_").replace("/","")
    return send_file(buf, as_attachment=True, download_name=filename,
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')


@app.route("/mecz/<int:match_id>/export/pdf")
@login_required
def export_match_pdf(match_id):
    db = get_db(); cur = db.cursor()
    cur.execute("SELECT * FROM matches WHERE id=%s", (match_id,))
    m = cur.fetchone()
    if not m: return redirect(url_for("historia"))

    gtk_name = (m.get("team_name_a","") or m.get("nazwa_gtk","") or "").strip() or get_team_short_name()
    name_opp = (m.get("team_name_b","") or m["przeciwnik"])
    dt = m['data_meczu'].strftime('%d.%m.%Y') if m['data_meczu'] else ""

    cur.execute("SELECT * FROM match_stats WHERE match_id=%s ORDER BY kwarta", (match_id,))
    all_stats = list(cur.fetchall())
    cur.execute("SELECT * FROM player_stats WHERE match_id=%s", (match_id,))
    all_players = list(cur.fetchall())
    cur.execute("SELECT * FROM timing_stats WHERE match_id=%s", (match_id,))
    all_timing = list(cur.fetchall())
    nr_name_map = build_nr_name_map(cur, match_id)
    play_time_secs = calc_play_time(match_id)
    lineup_html = build_lineup_section_html(cur, match_id, nr_name_map, play_time_secs)

    # ── Dane dla nowych sekcji PRZEBIEG i SHOOTING CHART (raport meczowy) ────
    # Score flow (przebieg punktowy minuta po minucie)
    try:
        cur.execute("""SELECT kwarta, czas_sek, pts_gtk, pts_opp FROM score_flow
                       WHERE match_id=%s ORDER BY kwarta ASC, czas_sek DESC""", (match_id,))
        _mr_flow_rows = list(cur.fetchall())
    except Exception:
        db.rollback(); _mr_flow_rows = []
    # Timeouty
    try:
        cur.execute("""SELECT druzyna, kwarta, czas_sek FROM match_timeouts
                       WHERE match_id=%s ORDER BY kwarta ASC, czas_sek DESC""", (match_id,))
        _mr_to_rows = list(cur.fetchall())
    except Exception:
        db.rollback(); _mr_to_rows = []
    # Strefy ataku — GTK i OPP (do side-by-side shooting chart na końcu raportu)
    _mr_zones_gtk = {}
    _mr_zones_opp = {}
    try:
        cur.execute("""SELECT druzyna, zone_id, made, att, stl, br, press
                       FROM zone_shots_team WHERE match_id=%s AND zone_id BETWEEN 1 AND 19""", (match_id,))
        for r in cur.fetchall():
            d = {"made": int(r["made"] or 0), "att": int(r["att"] or 0),
                 "stl":  int(r["stl"]  or 0), "br":  int(r["br"]  or 0),
                 "press":int(r["press"] or 0)}
            tgt = _mr_zones_gtk if r["druzyna"] == "gtk" else _mr_zones_opp
            tgt[int(r["zone_id"])] = d
    except Exception:
        db.rollback()
    cur.close()

    def build_suma(druzyna):
        s = {"pts":0,"poss":0,"p2m":0,"p2a":0,"p3m":0,"p3a":0,"ftm":0,"fta":0,"br":0,"fd":0,
             "ast":0,"oreb":0,"dreb":0,"stl":0,"blk":0,"d2m":0,"d2a":0,"przerw":0}
        for row in all_stats:
            if row["druzyna"]==druzyna:
                for k in s: s[k] += row.get(k,0) or 0
        return s

    suma_gtk = build_suma("gtk"); suma_opp = build_suma("opp")
    kpi_gtk  = calc_kpi(suma_gtk); kpi_opp = calc_kpi(suma_opp)

    winner = gtk_name if m['wynik_gtk']>m['wynik_opp'] else (name_opp if m['wynik_opp']>m['wynik_gtk'] else "Remis")

    def q_row(druzyna, qn, label, druzyna_rywal):
        q     = next((dict(r) for r in all_stats if r["druzyna"]==druzyna       and r["kwarta"]==qn), {})
        q_opp = next((dict(r) for r in all_stats if r["druzyna"]==druzyna_rywal and r["kwarta"]==qn), {})
        k       = calc_kpi(q)
        k_opp   = calc_kpi(q_opp)
        bg = "#f5f8ff" if qn%2==0 else "#fff"
        # NetRtg per kwarta = OFFrtg(A,Q) - DRtg(A,Q)
        # OFFrtg(A,Q) = pts_A * 100 / poss_A  — efektywność ataku A w kwarcie Q
        # DRtg(A,Q)   = ORtg rywala B w kwarcie Q = pts_B * 100 / poss_B — efektywność obrony A przez pryzmat ataku B
        net_val = None
        try:
            off_rtg = float(str(k['ortg']).replace('%',''))
            def_rtg = float(str(k_opp['ortg']).replace('%',''))
            net_val = off_rtg - def_rtg
            net_str = f"{net_val:+.1f}"
            net_col = "#1a6b3c" if net_val > 0 else ("#8b1a1a" if net_val < 0 else "#555")
        except:
            net_str = "—"; net_col = "#888"
        net_class = "net-pos" if (net_val is not None and net_val > 0) else ("net-neg" if (net_val is not None and net_val < 0) else "")
        return f"""<tr style="background:{bg}">
            <td class="left">{label}</td>
            <td>{q.get('pts',0)}</td>
            <td>{q.get('p2m',0)}/{q.get('p2a',0)}</td>
            <td>{q.get('p3m',0)}/{q.get('p3a',0)}</td>
            <td>{q.get('ftm',0)}/{q.get('fta',0)}</td>
            <td>{q.get('br',0)}</td>
            <td>{k['fg']}</td>
            <td>{k['efg']}</td>
            <td class="{net_class}" style="color:{net_col};font-weight:700">{net_str}</td>
        </tr>"""

    def player_rows(druzyna):
        players = sorted([p for p in all_players if p["druzyna"]==druzyna],
                         key=lambda x: x.get("pts",0) or 0, reverse=True)
        rows = ""
        for i, p in enumerate(players):
            fga  = (p.get("p2a",0) or 0) + (p.get("p3a",0) or 0)
            fta  = p.get("fta",0) or 0
            pm2  = p.get("p2m",0) or 0; pa2 = p.get("p2a",0) or 0
            pm3  = p.get("p3m",0) or 0; pa3 = p.get("p3a",0) or 0
            ftm  = p.get("ftm",0) or 0
            pts  = p.get("pts",0) or 0
            ast  = p.get("ast",0) or 0
            oreb = p.get("oreb",0) or 0
            dreb = p.get("dreb",0) or 0
            stl  = p.get("stl",0) or 0
            blk  = p.get("blk",0) or 0
            br   = p.get("br",0) or 0
            fin  = p.get("finishes",0) or 0
            efg  = f"{(pm2+1.5*pm3)/fga:.0%}" if fga else "—"
            ts   = f"{pts/(2*(fga+0.44*fta)):.0%}" if (fga+fta) else "—"
            p2pct = f"{pm2/pa2:.0%}" if pa2 else "—"
            p3pct = f"{pm3/pa3:.0%}" if pa3 else "—"
            ftpct = f"{ftm/fta:.0%}" if fta else "—"
            team_poss = max(sum(r.get("poss",0) or 0 for r in all_stats if r["druzyna"]==druzyna), 1)
            usg  = f"{(fga+0.44*fta+br)/team_poss:.0%}" if team_poss else "—"
            name = nr_name_map.get(str(p['nr']), f"#{p['nr']}")
            nr_html = f'<span style="color:#888;font-weight:400">#{p["nr"]}</span>'
            bg = "#f5f8ff" if i%2==0 else "#fff"
            _min_sec_pdf = int(p.get("min_sec", 0) or 0)
            _pt_secs_pdf = play_time_secs.get(int(p.get("nr") or 0), 0)
            if _min_sec_pdf > 0:
                czas_pdf = f"{_min_sec_pdf // 60}:{_min_sec_pdf % 60:02d}"
            elif _pt_secs_pdf > 0:
                czas_pdf = f"{int(_pt_secs_pdf)//60}:{int(_pt_secs_pdf)%60:02d}"
            else:
                czas_pdf = "—"
            rows += f"""<tr style="background:{bg}">
                <td class="left" style="min-width:90px">{name} {nr_html}</td>
                <td style="text-align:center">{czas_pdf}</td>
                <td style="text-align:center;font-weight:700;color:#1a2b4a">{pts}</td>
                <td style="text-align:center">{pm2}/{pa2}</td>
                <td style="text-align:center">{p2pct}</td>
                <td style="text-align:center">{pm3}/{pa3}</td>
                <td style="text-align:center">{p3pct}</td>
                <td style="text-align:center">{ftm}/{fta}</td>
                <td style="text-align:center">{ftpct}</td>
                <td style="text-align:center">{oreb}</td>
                <td style="text-align:center">{dreb}</td>
                <td style="text-align:center">{oreb+dreb}</td>
                <td style="text-align:center">{ast}</td>
                <td style="text-align:center">{br}</td>
                <td style="text-align:center">{stl}</td>
                <td style="text-align:center">{blk}</td>
                <td style="text-align:center;font-weight:600">{efg}</td>
                <td style="text-align:center">{ts}</td>
                <td style="text-align:center">{usg}</td>
                <td style="text-align:center">{fin}</td>
            </tr>"""
        return rows

    def timing_rows():
        rows = ""
        for i, b in enumerate(BUCKETS):
            # Sumuj po wszystkich kwartach (nie tylko pierwsza pasująca)
            grs = [r for r in all_timing if r["druzyna"]=="gtk" and r["bucket"]==b]
            ors = [r for r in all_timing if r["druzyna"]=="opp" and r["bucket"]==b]
            gm2 = sum(r.get("made2",0) for r in grs); ga2 = sum(r.get("att2",0) for r in grs)
            gm3 = sum(r.get("made3",0) for r in grs); ga3 = sum(r.get("att3",0) for r in grs)
            om2 = sum(r.get("made2",0) for r in ors); oa2 = sum(r.get("att2",0) for r in ors)
            om3 = sum(r.get("made3",0) for r in ors); oa3 = sum(r.get("att3",0) for r in ors)
            g_br = sum(r.get("br",0) for r in grs); o_br = sum(r.get("br",0) for r in ors)
            g_ft = sum(r.get("poss_ft",0) or (1 if r.get("ftm",0)>0 else 0) for r in grs)
            o_ft = sum(r.get("poss_ft",0) or (1 if r.get("ftm",0)>0 else 0) for r in ors)
            gm = gm2+gm3; ga = ga2+ga3
            om = om2+om3; oa = oa2+oa3
            if ga+ga2+ga3+g_br+g_ft+oa+oa2+oa3+o_br+o_ft == 0: continue
            # RAZEM = trafione + posiadania FT + chybione + BR
            g_total = gm + g_ft + (ga-gm) + g_br
            o_total = om + o_ft + (oa-om) + o_br
            ge = f"{gm/ga:.0%}" if ga else "—"
            oe = f"{om/oa:.0%}" if oa else "—"
            bg = "#f5f8ff" if i%2==0 else "#fff"
            rows += f"""<tr style="background:{bg}">
                <td style="font-weight:700;padding:3px 5px">{b}</td>
                <td style="text-align:center">{gm2 or '—'}</td>
                <td style="text-align:center">{gm3 or '—'}</td>
                <td style="text-align:center;color:#1a6b3c">{g_ft or '—'}</td>
                <td style="text-align:center;color:#8b1a1a">{(ga2-gm2) or '—'}</td>
                <td style="text-align:center;color:#8b1a1a">{(ga3-gm3) or '—'}</td>
                <td style="text-align:center;color:#8b1a1a">{g_br or '—'}</td>
                <td style="text-align:center;font-weight:700">{g_total or '—'}</td>
                <td style="text-align:center;font-weight:700;color:#1a6b3c">{ge}</td>
                <td style="width:8px"></td>
                <td style="text-align:center">{om2 or '—'}</td>
                <td style="text-align:center">{om3 or '—'}</td>
                <td style="text-align:center;color:#1a6b3c">{o_ft or '—'}</td>
                <td style="text-align:center;color:#8b1a1a">{(oa2-om2) or '—'}</td>
                <td style="text-align:center;color:#8b1a1a">{(oa3-om3) or '—'}</td>
                <td style="text-align:center;color:#8b1a1a">{o_br or '—'}</td>
                <td style="text-align:center;font-weight:700">{o_total or '—'}</td>
                <td style="text-align:center;font-weight:700;color:#8b1a1a">{oe}</td>
            </tr>"""
        return rows

    def timing_zone_rows():
        _TZ = [
            ("0–4s",   "Transition",   ["0s","1-4s"]),
            ("5–10s",  "Primary Off.", ["5-8s","9-12s"]),
            ("11–16s", "Late Offense", ["13-16s"]),
            ("17–24s", "End of Clock", ["17-20s","21-24s"]),
        ]
        _agg = {}
        for _r in (all_timing or []):
            _druz = str(_r.get("druzyna","")); _bkt = str(_r.get("bucket",""))
            if _druz not in ("gtk","opp") or not _bkt: continue
            _key = (_druz, _bkt)
            if _key not in _agg:
                _agg[_key] = {"made2":0,"att2":0,"made3":0,"att3":0,"br":0}
            for _k in ("made2","att2","made3","att3","br"):
                _agg[_key][_k] += int(_r.get(_k,0) or 0)
        rows = ""
        for i, (_lbl, _desc, _bkts) in enumerate(_TZ):
            _g = {"made2":0,"att2":0,"made3":0,"att3":0,"br":0}
            _o = {"made2":0,"att2":0,"made3":0,"att3":0,"br":0}
            for _b in _bkts:
                for _k in _g: _g[_k] += _agg.get(("gtk",_b),{}).get(_k,0)
                for _k in _o: _o[_k] += _agg.get(("opp",_b),{}).get(_k,0)
            _g_fga = _g["att2"]+_g["att3"]; _o_fga = _o["att2"]+_o["att3"]
            _g_fgm = _g["made2"]+_g["made3"]; _o_fgm = _o["made2"]+_o["made3"]
            _g_efg = f"{(_g['made2']+1.5*_g['made3'])/_g_fga:.0%}" if _g_fga else "—"
            _o_efg = f"{(_o['made2']+1.5*_o['made3'])/_o_fga:.0%}" if _o_fga else "—"
            _bg = "#f5f8ff" if i%2==0 else "#fff"
            rows += f"""<tr style="background:{_bg}">
                <td style="font-weight:700;padding:3px 6px">{_lbl}</td>
                <td style="padding:3px 6px;font-size:8.5px;color:#666">{_desc}</td>
                <td style="text-align:center;font-weight:700;color:#1a6b3c">{_g_fgm}/{_g_fga}</td>
                <td style="text-align:center;color:#1a6b3c">{_g_efg}</td>
                <td style="text-align:center;color:#888">{_g["br"]}</td>
                <td style="width:8px;background:#e8ecf3"></td>
                <td style="text-align:center;font-weight:700;color:#8b1a1a">{_o_fgm}/{_o_fga}</td>
                <td style="text-align:center;color:#8b1a1a">{_o_efg}</td>
                <td style="text-align:center;color:#888">{_o["br"]}</td>
            </tr>"""
        return rows

    def ft_br_html():
        _ag = {b: {"ft_g":0,"ft_o":0,"br_g":0,"br_o":0} for b in BUCKETS}
        for _r in (all_timing or []):
            _d = str(_r.get("druzyna","")); _b = str(_r.get("bucket",""))
            if _b not in BUCKETS: continue
            if _d == "gtk":
                _ag[_b]["ft_g"] += int(_r.get("poss_ft",0) or 0)
                _ag[_b]["br_g"] += int(_r.get("br",0) or 0)
            elif _d == "opp":
                _ag[_b]["ft_o"] += int(_r.get("poss_ft",0) or 0)
                _ag[_b]["br_o"] += int(_r.get("br",0) or 0)
        _ft_g_max = max((_ag[b]["ft_g"] for b in BUCKETS), default=0) or 1
        _ft_o_max = max((_ag[b]["ft_o"] for b in BUCKETS), default=0) or 1
        _br_g_max = max((_ag[b]["br_g"] for b in BUCKETS), default=0) or 1
        _br_o_max = max((_ag[b]["br_o"] for b in BUCKETS), default=0) or 1
        def _bc(val, mx, bg, col):
            pct = round(val/mx*100)
            return (f'<td style="text-align:center;padding:2px 3px">'
                    f'<div style="font-weight:700;font-size:9px;line-height:1.2">{val or "—"}</div>'
                    f'<div style="height:9px;background:{bg};border-radius:2px">'
                    f'<div style="height:100%;width:{pct}%;background:{col}"></div></div></td>')
        _bh = "".join(f'<th style="background:#1a2b4a;text-align:center;padding:2px 3px;font-size:7.5px">{b}</th>' for b in BUCKETS)
        _ft_g = "".join(_bc(_ag[b]["ft_g"],_ft_g_max,"#e8f5e9","#1a6b3c") for b in BUCKETS)
        _ft_o = "".join(_bc(_ag[b]["ft_o"],_ft_o_max,"#fce8e8","#8b1a1a") for b in BUCKETS)
        _br_g = "".join(_bc(_ag[b]["br_g"],_br_g_max,"#fff3e0","#c97400") for b in BUCKETS)
        _br_o = "".join(_bc(_ag[b]["br_o"],_br_o_max,"#fff3e0","#c97400") for b in BUCKETS)
        _gn = gtk_name; _on = name_opp
        return f"""<div class="two-col" style="margin-top:8px">
  <div class="section">
    <h3>FT Timing — kiedy pada faul</h3>
    <table style="width:100%"><thead><tr>
      <th style="background:#1a2b4a;text-align:left;padding:3px 5px;font-size:7.5px">Drużyna</th>{_bh}
    </tr></thead><tbody>
      <tr style="background:#f5f8ff"><td style="padding:3px 5px;font-weight:700;font-size:8px">{_gn}</td>{_ft_g}</tr>
      <tr><td style="padding:3px 5px;font-weight:700;font-size:8px">{_on}</td>{_ft_o}</tr>
    </tbody></table>
  </div>
  <div class="section">
    <h3>BR Timing — straty w zegarze</h3>
    <table style="width:100%"><thead><tr>
      <th style="background:#1a2b4a;text-align:left;padding:3px 5px;font-size:7.5px">Drużyna</th>{_bh}
    </tr></thead><tbody>
      <tr style="background:#f5f8ff"><td style="padding:3px 5px;font-weight:700;font-size:8px">{_gn}</td>{_br_g}</tr>
      <tr><td style="padding:3px 5px;font-weight:700;font-size:8px">{_on}</td>{_br_o}</tr>
    </tbody></table>
  </div>
</div>"""

    TH  = "style='background:#1a2b4a;color:#fff;padding:5px 8px;font-size:10px;text-align:center'"
    THL = "style='background:#1a2b4a;color:#fff;padding:5px 8px;font-size:10px'"
    THG = "style='background:#1a6b3c;color:#fff;padding:5px 8px;font-size:10px;text-align:center'"
    THR = "style='background:#8b1a1a;color:#fff;padding:5px 8px;font-size:10px;text-align:center'"
    THNET = "style='background:#534AB7;color:#fff;padding:5px 8px;font-size:10px;text-align:center'"

    # ── Czy GTK wygrało? ─────────────────────────────────────────────────────
    gtk_won = m['wynik_gtk'] > m['wynik_opp']

    # ── Sekcja porównania paskami (jak v4) ───────────────────────────────────
    # ── Tabela celności ────────────────────────────────────────────────────────
    def _pct(m, a): return f"{m/a:.1%}" if a else "—"
    def _efg(d):
        fga = d.get("p2a",0)+d.get("p3a",0)
        return f"{(d.get('p2m',0)+1.5*d.get('p3m',0))/fga:.1%}" if fga else "—"
    def _ts(d):
        fga = d.get("p2a",0)+d.get("p3a",0); fta = d.get("fta",0)
        return f"{d.get('pts',0)/(2*(fga+0.44*fta)):.1%}" if (fga+fta) else "—"
    def _topct(d):
        poss = max(d.get("poss",1),1)
        return f"{d.get('br',0)/poss:.1%}"
    def _td_cmp(g_val, o_val, better="high"):
        try:
            gn = float(str(g_val).replace('%','').replace('—','0').replace('/',''))
            on = float(str(o_val).replace('%','').replace('—','0').replace('/',''))
            g_wins = gn > on if better=="high" else gn < on
        except: g_wins = False
        gs = "font-weight:700;color:#0F6E56" if g_wins else ""
        os_ = "font-weight:700;color:#A32D2D" if (not g_wins and g_val!=o_val) else ""
        return f'<td style="text-align:center;{gs}">{g_val}</td><td style="text-align:center;{os_}">{o_val}</td>'

    cmp_section = f"""
<div style="margin-bottom:10px">
  <table style="width:100%;border-collapse:collapse;font-size:8.5px">
    <thead>
      <tr style="background:#1a2b4a;color:#fff">
        <th style="padding:4px 6px;text-align:left">Drużyna</th>
        <th style="padding:4px 5px;text-align:center" colspan="2">2PT M/A</th>
        <th style="padding:4px 5px;text-align:center">2PT%</th>
        <th style="padding:4px 5px;text-align:center" colspan="2">3PT M/A</th>
        <th style="padding:4px 5px;text-align:center">3PT%</th>
        <th style="padding:4px 5px;text-align:center" colspan="2">FT M/A</th>
        <th style="padding:4px 5px;text-align:center">FT%</th>
        <th style="padding:4px 5px;text-align:center">eFG%</th>
        <th style="padding:4px 5px;text-align:center">TS%</th>
        <th style="padding:4px 5px;text-align:center">TO%</th>
      </tr>
    </thead>
    <tbody>
      <tr style="background:#f0fff4">
        <td style="padding:4px 6px;font-weight:700;color:#0F6E56">{gtk_name}</td>
        <td style="text-align:center">{suma_gtk.get('p2m',0)}</td>
        <td style="text-align:center">{suma_gtk.get('p2a',0)}</td>
        <td style="text-align:center;font-weight:700">{_pct(suma_gtk.get('p2m',0),suma_gtk.get('p2a',0))}</td>
        <td style="text-align:center">{suma_gtk.get('p3m',0)}</td>
        <td style="text-align:center">{suma_gtk.get('p3a',0)}</td>
        <td style="text-align:center;font-weight:700">{_pct(suma_gtk.get('p3m',0),suma_gtk.get('p3a',0))}</td>
        <td style="text-align:center">{suma_gtk.get('ftm',0)}</td>
        <td style="text-align:center">{suma_gtk.get('fta',0)}</td>
        <td style="text-align:center;font-weight:700">{_pct(suma_gtk.get('ftm',0),suma_gtk.get('fta',0))}</td>
        <td style="text-align:center;font-weight:700">{_efg(suma_gtk)}</td>
        <td style="text-align:center;font-weight:700">{_ts(suma_gtk)}</td>
        <td style="text-align:center">{_topct(suma_gtk)}</td>
      </tr>
      <tr style="background:#fff5f5">
        <td style="padding:4px 6px;font-weight:700;color:#A32D2D">{name_opp}</td>
        <td style="text-align:center">{suma_opp.get('p2m',0)}</td>
        <td style="text-align:center">{suma_opp.get('p2a',0)}</td>
        <td style="text-align:center;font-weight:700">{_pct(suma_opp.get('p2m',0),suma_opp.get('p2a',0))}</td>
        <td style="text-align:center">{suma_opp.get('p3m',0)}</td>
        <td style="text-align:center">{suma_opp.get('p3a',0)}</td>
        <td style="text-align:center;font-weight:700">{_pct(suma_opp.get('p3m',0),suma_opp.get('p3a',0))}</td>
        <td style="text-align:center">{suma_opp.get('ftm',0)}</td>
        <td style="text-align:center">{suma_opp.get('fta',0)}</td>
        <td style="text-align:center;font-weight:700">{_pct(suma_opp.get('ftm',0),suma_opp.get('fta',0))}</td>
        <td style="text-align:center;font-weight:700">{_efg(suma_opp)}</td>
        <td style="text-align:center;font-weight:700">{_ts(suma_opp)}</td>
        <td style="text-align:center">{_topct(suma_opp)}</td>
      </tr>
    </tbody>
  </table>
</div>"""

    # ── Clutch — ostatnie 1/3 posiadań Q4/OT (ceil) — UKŁAD JAK W PROGRAMIE ──
    import math as _math
    CLUTCH_KEYS = ["pts","poss","p2m","p2a","p3m","p3a","ftm","fta","br","fd",
                   "ast","oreb","dreb","stl","blk","d2m","d2a"]
    def _clutch_val(druzyna):
        """Zbiera Q4+ statystyki i aplikuje ratio ceil(poss/3)/poss."""
        qtrs = sorted({r["kwarta"] for r in all_stats
                       if r.get("kwarta",0) >= 4 and r.get("druzyna")==druzyna})
        out = {k:0 for k in CLUTCH_KEYS}
        clutch_poss = 0
        for qn in qtrs:
            qd = next((dict(r) for r in all_stats if r["druzyna"]==druzyna and r["kwarta"]==qn), {})
            poss = qd.get("poss",0) or 0
            cp   = _math.ceil(poss/3) if poss else 0
            ratio = cp/poss if poss else 0
            for k in CLUTCH_KEYS:
                if k == "poss": continue
                out[k] += round((qd.get(k,0) or 0) * ratio)
            clutch_poss += cp
        out["poss"] = clutch_poss
        return out

    cg = _clutch_val("gtk"); co = _clutch_val("opp")
    # Lista kwart clutch (np. Q4, Q4+Q5 jeśli OT)
    _clutch_qtrs = sorted({r["kwarta"] for r in all_stats
                            if r.get("kwarta",0) >= 4 and r.get("druzyna") in ("gtk","opp")})
    _qtrs_label = "+".join(f"Q{q}" for q in _clutch_qtrs) if _clutch_qtrs else "Q4"

    # Pomocnicze
    def _cpct(m, a): return f"{round(m/a*100)}%" if a else "—"
    def _cppp(p, ps): return f"{p/ps:.2f}" if ps else "—"
    def _cto(b, ps): return f"{round(b/ps*100)}%" if ps else "—"

    _c_efg_g = _cpct(cg["p2m"]+int(1.5*cg["p3m"]), cg["p2a"]+cg["p3a"])
    _c_efg_o = _cpct(co["p2m"]+int(1.5*co["p3m"]), co["p2a"]+co["p3a"])
    _c_p2p_g = _cpct(cg["p2m"], cg["p2a"]); _c_p2p_o = _cpct(co["p2m"], co["p2a"])
    _c_p3p_g = _cpct(cg["p3m"], cg["p3a"]); _c_p3p_o = _cpct(co["p3m"], co["p3a"])
    _c_ftp_g = _cpct(cg["ftm"], cg["fta"]); _c_ftp_o = _cpct(co["ftm"], co["fta"])
    _c_ppp_g = _cppp(cg["pts"], cg["poss"]); _c_ppp_o = _cppp(co["pts"], co["poss"])
    _c_to_g  = _cto(cg["br"], cg["poss"]);   _c_to_o = _cto(co["br"], co["poss"])
    _c_ortg_g = round(cg["pts"]/cg["poss"]*100) if cg["poss"] else 0
    _c_ortg_o = round(co["pts"]/co["poss"]*100) if co["poss"] else 0
    _c_net_g  = _c_ortg_g - _c_ortg_o
    _c_net_gs = ("+"+str(_c_net_g)) if _c_net_g>0 else str(_c_net_g)
    _c_net_os = ("+"+str(-_c_net_g)) if _c_net_g<0 else str(-_c_net_g) if _c_net_g else "0"

    _cwin_gtk = cg["pts"] > co["pts"]
    _cwin_opp = co["pts"] > cg["pts"]
    _c_sc_g = "#1a6b3c" if _cwin_gtk else ("#8b1a1a" if _cwin_opp else "#856404")
    _c_sc_o = "#1a6b3c" if _cwin_opp else ("#8b1a1a" if _cwin_gtk else "#856404")
    _c_net_color = "#1a6b3c" if _c_net_g>0 else ("#8b1a1a" if _c_net_g<0 else "#856404")
    _c_wc     = f"{gtk_name} lepsza" if _cwin_gtk else ("Rywal lepszy" if _cwin_opp else "Remis")
    _c_wc_bg  = "#e8f5e9" if _cwin_gtk else ("#ffebee" if _cwin_opp else "#fff8e1")
    _c_wc_col = "#1a6b3c" if _cwin_gtk else ("#8b1a1a" if _cwin_opp else "#856404")

    def _ccol(vg, vo, higher=True):
        try:
            fg=float(str(vg).replace('%','').replace('—','0').replace('+',''))
            fo=float(str(vo).replace('%','').replace('—','0').replace('+',''))
            if higher: return ("#1a6b3c" if fg>fo else "#8b1a1a" if fg<fo else "#888"), \
                              ("#1a6b3c" if fo>fg else "#8b1a1a" if fo<fg else "#888")
            else:      return ("#1a6b3c" if fg<fo else "#8b1a1a" if fg>fo else "#888"), \
                              ("#1a6b3c" if fo<fg else "#8b1a1a" if fo>fg else "#888")
        except: return "#1a2b4a","#1a2b4a"

    def _eff_pill(lbl, vg, vo, higher=True, neutral=False):
        if neutral: cgc = coc = "#1a2b4a"
        else: cgc, coc = _ccol(vg, vo, higher=higher)
        return (f'<div style="flex:1;background:#f4f6fb;border-radius:8px;padding:8px 6px;text-align:center;min-width:0;border:0.5px solid #e3e8f0">'
                f'<div style="font-size:8px;color:#999;text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px">{lbl}</div>'
                f'<div style="display:flex;align-items:center;justify-content:center;gap:5px">'
                f'<span style="font-size:12px;font-weight:700;color:{cgc}">{vg}</span>'
                f'<span style="font-size:8px;color:#bbb">vs</span>'
                f'<span style="font-size:12px;font-weight:700;color:{coc}">{vo}</span>'
                f'</div></div>')

    _c_ast_to_g = f"{cg['ast']/cg['br']:.2f}" if cg.get("br") else "—"
    _c_ast_to_o = f"{co['ast']/co['br']:.2f}" if co.get("br") else "—"
    _eff_strip_clutch = (_eff_pill("eFG%",   _c_efg_g,    _c_efg_o) +
                         _eff_pill("AST/TO", _c_ast_to_g, _c_ast_to_o) +
                         _eff_pill("TO%",    _c_to_g,     _c_to_o,  higher=False) +
                         _eff_pill("PPP",    _c_ppp_g,    _c_ppp_o))

    def _face_bar(lbl, mg, ag, mo, ao, pts_type=""):
        pg = _cpct(mg, ag); po = _cpct(mo, ao)
        max_w = 46
        wg = round(float(str(pg).replace('%','') or 0) / 100 * max_w) if ag else 0
        wo = round(float(str(po).replace('%','') or 0) / 100 * max_w) if ao else 0
        badge_bg = "#2e5090" if pts_type=="3PT" else ("#856404" if pts_type=="FT" else "#1a6b3c")
        return f"""
<div style="margin-bottom:10px">
  <div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">
    <span style="font-size:9px;font-weight:700;color:#fff;background:{badge_bg};border-radius:3px;padding:1px 6px">{lbl}</span>
    <span style="font-size:9px;color:#888">{mg}/{ag}</span>
    <span style="flex:1;height:1px;background:#e8ecf0"></span>
    <span style="font-size:9px;color:#888">{mo}/{ao}</span>
  </div>
  <div style="display:flex;align-items:center;gap:3px">
    <span style="font-size:11px;font-weight:700;color:{_c_sc_g};width:34px;text-align:right">{pg}</span>
    <div style="flex:1;display:flex;height:14px;border-radius:3px;overflow:hidden;background:#eef0f5">
      <div style="flex:1;display:flex;justify-content:flex-end;align-items:center">
        <div style="width:{wg}%;height:100%;background:#1a6b3c;border-radius:2px 0 0 2px"></div>
      </div>
      <div style="width:2px;background:#fff;flex-shrink:0"></div>
      <div style="flex:1;display:flex;align-items:center">
        <div style="width:{wo}%;height:100%;background:#8b1a1a;border-radius:0 2px 2px 0"></div>
      </div>
    </div>
    <span style="font-size:11px;font-weight:700;color:{_c_sc_o};width:34px">{po}</span>
  </div>
</div>"""

    _face_bars_clutch = (_face_bar("2PT", cg["p2m"],cg["p2a"],co["p2m"],co["p2a"],"2PT") +
                         _face_bar("3PT", cg["p3m"],cg["p3a"],co["p3m"],co["p3a"],"3PT") +
                         _face_bar("FT",  cg["ftm"],cg["fta"],co["ftm"],co["fta"],"FT"))

    def _srow(lbl, vg, vo, higher=True, neutral=False):
        if neutral: cgs = cos = "#1a2b4a"
        else:       cgs, cos = _ccol(vg, vo, higher=higher)
        return (f'<div style="display:flex;align-items:center;padding:4px 0;border-bottom:0.5px solid #eceef2">'
                f'<span style="flex:1;font-size:11px;font-weight:600;color:{cgs};text-align:right;padding-right:10px">{vg}</span>'
                f'<span style="width:80px;font-size:9px;color:#999;text-align:center;text-transform:uppercase;letter-spacing:.4px;flex-shrink:0">{lbl}</span>'
                f'<span style="flex:1;font-size:11px;font-weight:600;color:{cos};text-align:left;padding-left:10px">{vo}</span>'
                f'</div>')

    _stat_rows_clutch = (
        _srow("AST",    cg["ast"],  co["ast"]) +
        _srow("STL",    cg["stl"],  co["stl"]) +
        _srow("BLK",    cg["blk"],  co["blk"]) +
        _srow("ZB Off", cg["oreb"], co["oreb"]) +
        _srow("ZB Def", cg["dreb"], co["dreb"]) +
        _srow("DOB M/A", f"{cg['d2m']}/{cg['d2a']}", f"{co['d2m']}/{co['d2a']}", neutral=True) +
        _srow("FD",     cg["fd"],   co["fd"]) +
        _srow("TO",     cg["br"],   co["br"],  higher=False) +
        _srow("TO%",    _c_to_g,    _c_to_o,    higher=False) +
        _srow("NETrtg", _c_net_gs,  _c_net_os)
    )

    _c_ortg_gs = str(_c_ortg_g) if cg["poss"] else "—"
    _c_ortg_os = str(_c_ortg_o) if co["poss"] else "—"

    clutch_section = f"""
<div class="section" style="page-break-inside:avoid">
  <div style="border-radius:8px;overflow:hidden;border:0.5px solid #e3e8f0;background:#fff">
    <!-- HEADER -->
    <div style="padding:8px 14px;display:flex;align-items:center;gap:8px;border-bottom:0.5px solid #eceef2;background:#f8f9fc">
      <span style="background:#EF9F27;color:#fff;padding:2px 9px;border-radius:18px;font-size:10px;font-weight:700;letter-spacing:.4px">{_qtrs_label} CLUTCH</span>
      <span style="font-size:10px;color:#aaa">Ostatnie 1/3 posiadań Q4</span>
      <span style="margin-left:auto;background:{_c_wc_bg};color:{_c_wc_col};padding:2px 9px;border-radius:18px;font-size:10px;font-weight:600">{_c_wc} w clutch</span>
    </div>
    <!-- SCOREBOARD -->
    <div style="display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:14px;gap:10px;border-bottom:0.5px solid #eceef2">
      <div style="text-align:right">
        <div style="font-size:10px;font-weight:600;color:#888;text-transform:uppercase;letter-spacing:.5px;margin-bottom:3px">{gtk_name}</div>
        <div style="font-size:38px;font-weight:800;color:{_c_sc_g};line-height:1">{cg["pts"]}</div>
        <div style="font-size:10px;color:#aaa;margin-top:4px">ORtg <span style="color:#555;font-weight:600">{_c_ortg_gs}</span></div>
      </div>
      <div style="text-align:center;padding:0 6px">
        <div style="font-size:10px;color:#bbb;font-weight:400;margin-bottom:6px">vs</div>
        <div style="background:#f4f6fb;border-radius:6px;padding:5px 10px;border:0.5px solid #e3e8f0">
          <div style="font-size:8px;color:#aaa;text-transform:uppercase;letter-spacing:.4px">NETrtg</div>
          <div style="font-size:15px;font-weight:800;color:{_c_net_color}">{_c_net_gs}</div>
        </div>
      </div>
      <div style="text-align:left">
        <div style="font-size:10px;font-weight:600;color:#888;text-transform:uppercase;letter-spacing:.5px;margin-bottom:3px">{name_opp}</div>
        <div style="font-size:38px;font-weight:800;color:{_c_sc_o};line-height:1">{co["pts"]}</div>
        <div style="font-size:10px;color:#aaa;margin-top:4px">ORtg <span style="color:#555;font-weight:600">{_c_ortg_os}</span></div>
      </div>
    </div>
    <!-- EFFICIENCY STRIP -->
    <div style="display:flex;gap:5px;padding:8px 14px;border-bottom:0.5px solid #eceef2;background:#fafbfd">
      {_eff_strip_clutch}
    </div>
    <!-- SHOOTING FACE-OFF -->
    <div style="padding:10px 14px;border-bottom:0.5px solid #eceef2">
      <div style="font-size:8px;color:#aaa;text-transform:uppercase;letter-spacing:.6px;margin-bottom:7px;display:flex;align-items:center;gap:6px">
        <span style="color:#1a6b3c;font-weight:700">{gtk_name}</span>
        <span style="flex:1;height:1px;background:#eceef2"></span>
        <span>{"Rzuty z pola" if get_portal_lang()=='pl' else 'Field goals'}</span>
        <span style="flex:1;height:1px;background:#eceef2"></span>
        <span style="color:#8b1a1a;font-weight:700">{name_opp}</span>
      </div>
      {_face_bars_clutch}
    </div>
    <!-- STAT TABLE -->
    <div style="padding:8px 14px 10px">
      <div style="font-size:8px;color:#aaa;text-transform:uppercase;letter-spacing:.6px;margin-bottom:6px">Szczegółowe statystyki</div>
      <div style="display:flex;align-items:center;margin-bottom:3px">
        <span style="flex:1;font-size:9px;font-weight:700;color:#1a6b3c;text-align:right;padding-right:10px">{gtk_name}</span>
        <span style="width:80px;flex-shrink:0"></span>
        <span style="flex:1;font-size:9px;font-weight:700;color:#8b1a1a;text-align:left;padding-left:10px">{name_opp}</span>
      </div>
      {_stat_rows_clutch}
    </div>
    <div style="padding:4px 14px 6px;font-size:9px;color:#bbb;border-top:0.5px solid #eceef2;background:#fafbfd">
      Ostatnie 1/3 posiadań Q4 (zaokr. w górę) — GTK: {cg["poss"]} pos., Rywal: {co["poss"]} pos.
    </div>
  </div>
</div>"""

    # ══════════════════════════════════════════════════════════════════════════
    # SCORE FLOW — wykres SVG kumulacyjnych punktów + timeouty (między ZAWODNIKAMI a PRZEBIEGIEM)
    # ══════════════════════════════════════════════════════════════════════════
    _final_g = int(m.get("wynik_gtk") or 0); _final_o = int(m.get("wynik_opp") or 0)
    _flow_xy = [(0.0, 0, 0)]
    for _fr in _mr_flow_rows:
        _q = _fr["kwarta"] or 1; _t = _fr["czas_sek"] or 0
        _em = ((_q - 1) * 600 + max(0, 600 - int(_t))) / 60.0
        _flow_xy.append((round(_em, 2), int(_fr["pts_gtk"] or 0), int(_fr["pts_opp"] or 0)))
    _flow_xy.append((40.0, _final_g, _final_o))
    _flow_xy = sorted(_flow_xy, key=lambda p: p[0])
    _mg = _mo = 0; _flow_mono = []
    for _x, _g, _o in _flow_xy:
        _mg = max(_mg, _g); _mo = max(_mo, _o)
        _flow_mono.append((_x, _mg, _mo))
    _seen_x = {}
    for _pt in _flow_mono: _seen_x[_pt[0]] = _pt
    _flow_xy = sorted(_seen_x.values(), key=lambda p: p[0])
    # SVG ramka
    _y_max = max(_final_g, _final_o, 10)
    _y_top = ((_y_max // 10) + 1) * 10
    SVG_W = 1100; SVG_H = 300
    PAD_L, PAD_R, PAD_T, PAD_B = 36, 14, 12, 24
    PLOT_W = SVG_W - PAD_L - PAD_R; PLOT_H = SVG_H - PAD_T - PAD_B
    def _sx(m_): return PAD_L + (m_ / 40.0) * PLOT_W
    def _sy(pts): return PAD_T + PLOT_H - (pts / max(_y_top, 1)) * PLOT_H
    # Linie kwart (10, 20, 30 min) + label
    _grid = ""
    for _qm in (10, 20, 30):
        _gx = _sx(_qm)
        _grid += f'<line x1="{_gx:.1f}" y1="{PAD_T}" x2="{_gx:.1f}" y2="{PAD_T+PLOT_H}" stroke="#dbe1ea" stroke-width="1" stroke-dasharray="3,3"/>'
        _grid += f'<text x="{_gx:.1f}" y="{PAD_T-2}" font-size="9" fill="#999" text-anchor="middle">Q{_qm//10}|Q{_qm//10+1}</text>'
    _yticks = ""
    _step = 10 if _y_top <= 60 else 20
    for _v in range(0, _y_top + 1, _step):
        _yy = _sy(_v)
        _yticks += f'<line x1="{PAD_L}" y1="{_yy:.1f}" x2="{PAD_L+PLOT_W}" y2="{_yy:.1f}" stroke="#f0f3f7" stroke-width="0.5"/>'
        _yticks += f'<text x="{PAD_L-4}" y="{_yy+3:.1f}" font-size="8.5" fill="#999" text-anchor="end">{_v}</text>'
    _xticks = ""
    for _v in range(0, 41, 5):
        _xx = _sx(_v)
        _xticks += f'<text x="{_xx:.1f}" y="{SVG_H-7}" font-size="8.5" fill="#999" text-anchor="middle">{_v}\'</text>'
    _pts_g_pl = " ".join(f"{_sx(x):.1f},{_sy(g):.1f}" for x,g,o in _flow_xy)
    _pts_o_pl = " ".join(f"{_sx(x):.1f},{_sy(o):.1f}" for x,g,o in _flow_xy)
    def _score_at_min(t, team_idx):
        v = 0
        for x, g, o in _flow_xy:
            if x <= t: v = (g if team_idx == 0 else o)
            else: break
        return v
    _to_dots_sf = ""
    for r in _mr_to_rows:
        _q = r["kwarta"] or 1; _t = r["czas_sek"] or 0
        _em = ((_q - 1) * 600 + max(0, 600 - int(_t))) / 60.0
        _ti = 0 if r["druzyna"] == "gtk" else 1
        _yv = _score_at_min(_em, _ti)
        _col = "#27ae60" if r["druzyna"] == "gtk" else "#e74c3c"
        _to_dots_sf += f'<circle cx="{_sx(_em):.1f}" cy="{_sy(_yv):.1f}" r="5.5" fill="{_col}" stroke="#fff" stroke-width="1.4" opacity="0.95"/>'

    _scoreflow_section = f"""
<div class="section" style="margin-top:8px">
  <h3>Score Flow — punkty kumulatywne &amp; timeouty</h3>
  <div style="background:#fff;border:1px solid #e8ecf3;border-radius:5px;padding:8px 10px">
    <div style="display:flex;gap:16px;font-size:9px;color:#555;margin-bottom:4px;flex-wrap:wrap">
      <span><span style="display:inline-block;width:18px;height:3px;background:#1a6b3c;border-radius:2px;vertical-align:middle"></span> {gtk_name}</span>
      <span><span style="display:inline-block;width:18px;height:3px;background:#8b1a1a;border-radius:2px;vertical-align:middle"></span> {name_opp}</span>
      <span><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#27ae60;border:1px solid #fff;vertical-align:middle"></span> T ({gtk_name})</span>
      <span><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:#e74c3c;border:1px solid #fff;vertical-align:middle"></span> T ({name_opp})</span>
      <span style="margin-left:auto;color:#888">Końcowy: <b>{_final_g}</b> – <b>{_final_o}</b></span>
    </div>
    <svg viewBox="0 0 {SVG_W} {SVG_H}" style="width:100%;height:auto;display:block">
      <rect x="{PAD_L}" y="{PAD_T}" width="{PLOT_W}" height="{PLOT_H}" fill="#fbfcfe" stroke="#e8ecf3" stroke-width="1"/>
      {_yticks}{_grid}{_xticks}
      <polyline points="{_pts_g_pl}" fill="none" stroke="#1a6b3c" stroke-width="2.2" stroke-linejoin="round"/>
      <polyline points="{_pts_o_pl}" fill="none" stroke="#8b1a1a" stroke-width="2.2" stroke-linejoin="round"/>
      {_to_dots_sf}
    </svg>
  </div>
</div>"""

    # ══════════════════════════════════════════════════════════════════════════
    # PRZEBIEG — UKŁAD JAK W PROGRAMIE: momentum_table + key_moments_table
    # ══════════════════════════════════════════════════════════════════════════
    timeout_rows = _mr_to_rows   # alias zgodny z nazwą używaną w /mecz

    # ── MOMENTUM TABLE — W/L badges + per-Q stats (PKT, eFG%, TO, POSS) ──────
    _q_results = []
    _mom_rows_html = ""
    for _qn in [1, 2, 3, 4]:
        _qs_g = next((r for r in all_stats if r["druzyna"]=="gtk" and r["kwarta"]==_qn), {})
        _qs_o = next((r for r in all_stats if r["druzyna"]=="opp" and r["kwarta"]==_qn), {})
        _qg = int(_qs_g.get("pts",0) or 0); _qo = int(_qs_o.get("pts",0) or 0)
        _q_winner = "gtk" if _qg > _qo else ("opp" if _qo > _qg else "tie")
        _q_results.append(_q_winner)

        def _mt_efg(qs):
            p2a=int(qs.get("p2a",0) or 0); p3a=int(qs.get("p3a",0) or 0)
            p2m=int(qs.get("p2m",0) or 0); p3m=int(qs.get("p3m",0) or 0)
            return f"{round((p2m+1.5*p3m)/(p2a+p3a)*100)}%" if (p2a+p3a) else "—"
        _g_efg = _mt_efg(_qs_g); _o_efg = _mt_efg(_qs_o)
        _g_to  = int(_qs_g.get("br",0) or 0); _o_to = int(_qs_o.get("br",0) or 0)
        _g_ps  = int(_qs_g.get("poss",0) or 0); _o_ps = int(_qs_o.get("poss",0) or 0)

        if _q_winner == "gtk":
            _res_html = f'<span style="background:#e8f5e9;color:#1a6b3c;border-radius:4px;padding:2px 7px;font-size:9px;font-weight:700">W +{_qg-_qo}</span>'
        elif _q_winner == "opp":
            _res_html = f'<span style="background:#ffebee;color:#8b1a1a;border-radius:4px;padding:2px 7px;font-size:9px;font-weight:700">L -{_qo-_qg}</span>'
        else:
            _res_html = '<span style="background:#eee;color:#666;border-radius:4px;padding:2px 7px;font-size:9px;font-weight:600">=</span>'

        def _ci(a, b, higher=True):
            try: ai = int(str(a).rstrip('%')); bi = int(str(b).rstrip('%'))
            except: return ""
            if higher:
                return "#1a6b3c" if ai > bi else ("#8b1a1a" if ai < bi else "")
            else:
                return "#1a6b3c" if ai < bi else ("#8b1a1a" if ai > bi else "")
        _c_g_pkt = "#1a6b3c" if _qg > _qo else ("#8b1a1a" if _qg < _qo else "")
        _c_o_pkt = "#1a6b3c" if _qo > _qg else ("#8b1a1a" if _qo < _qg else "")
        _c_g_efg = _ci(_g_efg, _o_efg, higher=True)
        _c_o_efg = _ci(_o_efg, _g_efg, higher=True)
        _c_g_to  = "#1a6b3c" if _g_to < _o_to else ("#8b1a1a" if _g_to > _o_to else "")
        _c_o_to  = "#1a6b3c" if _o_to < _g_to else ("#8b1a1a" if _o_to > _g_to else "")

        _qcol_bg = {1:"#dbe7f5",2:"#ffe0b3",3:"#c5e8c5",4:"#f5c5c5"}[_qn]
        _mom_rows_html += (
            f'<tr style="font-size:9.5px">'
            f'<td style="padding:4px 8px;text-align:left"><span style="background:{_qcol_bg};color:#1a2b4a;border-radius:4px;padding:2px 7px;font-size:9px;font-weight:700">{_qn}Q</span></td>'
            f'<td style="padding:4px 8px;text-align:center">{_res_html}</td>'
            f'<td style="padding:4px 8px;text-align:center;font-weight:600;color:{_c_g_pkt or "#1a2b4a"}">{_qg}</td>'
            f'<td style="padding:4px 8px;text-align:center;color:{_c_g_efg or "#444"}">{_g_efg}</td>'
            f'<td style="padding:4px 8px;text-align:center;color:{_c_g_to or "#444"}">{_g_to}</td>'
            f'<td style="padding:4px 8px;text-align:center;color:#666">{_g_ps}</td>'
            f'<td style="padding:4px 8px;text-align:center;font-weight:600;color:{_c_o_pkt or "#1a2b4a"};border-left:2px solid #e0e0e0">{_qo}</td>'
            f'<td style="padding:4px 8px;text-align:center;color:{_c_o_efg or "#444"}">{_o_efg}</td>'
            f'<td style="padding:4px 8px;text-align:center;color:{_c_o_to or "#444"}">{_o_to}</td>'
            f'<td style="padding:4px 8px;text-align:center;color:#666">{_o_ps}</td>'
            f'</tr>'
        )
    # Streak / best
    _streak_html = ""
    for r in _q_results:
        _col = "#1a6b3c" if r=="gtk" else ("#8b1a1a" if r=="opp" else "#888")
        _lbl = "W" if r=="gtk" else ("L" if r=="opp" else "=")
        _streak_html += (f'<span style="display:inline-flex;align-items:center;justify-content:center;'
                         f'width:22px;height:22px;border-radius:50%;background:{_col};color:#fff;'
                         f'font-size:10px;font-weight:600;margin-right:4px">{_lbl}</span>')
    _best = _cur = 0
    for r in _q_results:
        _cur = _cur+1 if r=="gtk" else 0
        _best = max(_best, _cur)
    _best_html = (f'<span style="font-size:10px;color:#666;margin-left:6px">Najlepsza seria: '
                  f'<b style="color:#1a6b3c">{_best} {"kwarty" if _best>1 else "kwarta"}</b></span>') if _best >= 1 else ""

    _gtk_s = gtk_name.upper()[:18]; _opp_s = name_opp.upper()[:16]
    _momentum_html = f"""
<div style="background:#fff;border:1px solid #e8ecf3;border-radius:5px;margin-bottom:8px">
  <div style="padding:8px 12px;display:flex;align-items:center;gap:6px;flex-wrap:wrap;border-bottom:0.5px solid #f0f2f6">
    {_streak_html}{_best_html}
  </div>
  <div style="overflow-x:auto">
    <table style="width:100%;border-collapse:collapse;font-size:9.5px">
      <thead>
        <tr style="background:#fafbfd">
          <th rowspan="2" style="padding:6px 8px;text-align:left;font-size:9px;color:#888;text-transform:uppercase;letter-spacing:.4px;border-bottom:0.5px solid #e0e0e0;vertical-align:middle">Q</th>
          <th rowspan="2" style="padding:6px 8px;text-align:center;font-size:9px;color:#888;text-transform:uppercase;letter-spacing:.4px;border-bottom:0.5px solid #e0e0e0;vertical-align:middle">Wynik</th>
          <th colspan="4" style="padding:5px 8px;text-align:center;font-size:9px;color:#1a6b3c;font-weight:700;letter-spacing:.3px">{_gtk_s}</th>
          <th colspan="4" style="padding:5px 8px;text-align:center;font-size:9px;color:#8b1a1a;font-weight:700;letter-spacing:.3px;border-left:2px solid #e0e0e0">{_opp_s}</th>
        </tr>
        <tr style="background:#fafbfd">
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">PKT</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">eFG%</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">TO</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">POSS</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0;border-left:2px solid #e0e0e0">PKT</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">eFG%</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">TO</th>
          <th style="padding:3px 8px 5px;font-size:8px;color:#888;border-bottom:0.5px solid #e0e0e0">POSS</th>
        </tr>
      </thead>
      <tbody>{_mom_rows_html}</tbody>
    </table>
  </div>
</div>"""

    # ── KEY MOMENTS — timeline akcji po każdym timeoucie (z parsowaniem Excela) ─
    def _fmt_to_time(czas_sek):
        el = max(0, 600 - int(czas_sek or 0))
        return f"{el//60}:{el%60:02d}"

    # Wczytaj plik Excel — buduj indeks wierszy per arkusz/kwarta
    sheets_all_k = {0: {}, 1: {}}
    sheets_tos_k = {0: {}, 1: {}}
    try:
        import os as _osK; import openpyxl as _opxK
        _epath = (m.get("file_path") or "") if (m.get("file_path") and _osK.path.exists(m.get("file_path",""))) \
                 else _osK.path.join(MATCH_FILES_DIR, f"{match_id}.xlsx")
        if _osK.path.exists(_epath):
            _wbK = _opxK.load_workbook(_epath, data_only=True)
            _snK = [s for s in _wbK.sheetnames if s.upper() not in ("META","KODY","LEGENDA")]
            for _si, _sn in enumerate(_snK[:2]):
                _rows = []
                for _rv in _wbK[_sn].iter_rows(min_row=2, values_only=True):
                    if any(v is not None for v in _rv):
                        _rows.append(list(_rv))
                q_all = {}; q_tos = {}
                for i, row in enumerate(_rows):
                    try: qn = int(float(str(row[0]))) if row[0] is not None else None
                    except: qn = None
                    if qn is None: continue
                    try: elapsed_B = float(row[1]) if row[1] is not None else 0.0
                    except: elapsed_B = 0.0
                    codes = []
                    for j in range(5):
                        if i + j < len(_rows):
                            cv = _rows[i+j][2] if len(_rows[i+j]) > 2 else None
                            codes.append(str(cv) if cv is not None else "—")
                        else:
                            codes.append("—")
                    q_all.setdefault(qn, []).append((elapsed_B, codes))
                    # is_to: kolumna J (index 9)
                    if len(row) > 9:
                        v = row[9]
                        is_to = (v is True) or (str(v).strip().upper() in ("T","TAK","1","TRUE") if v is not None else False)
                        if is_to:
                            q_tos.setdefault(qn, []).append((elapsed_B, codes))
                sheets_all_k[_si] = q_all
                sheets_tos_k[_si] = q_tos
            _wbK.close()
    except Exception:
        pass

    def _get_codes_k(sidx_own, sidx_target, qn, idx_own):
        tos_own = sheets_tos_k.get(sidx_own, {}).get(qn, [])
        if idx_own >= len(tos_own): return []
        own_elapsed, own_codes = tos_own[idx_own]
        if sidx_target == sidx_own: return own_codes
        all_own   = sheets_all_k.get(sidx_own,   {}).get(qn, [])
        all_other = sheets_all_k.get(sidx_target, {}).get(qn, [])
        if not all_other: return []
        total_own   = all_own[-1][0]   if all_own   else 0
        total_other = all_other[-1][0] if all_other else 0
        target = (own_elapsed / total_own * total_other) if (total_own > 0 and total_other > 0) else own_elapsed
        _, closest_codes = min(all_other, key=lambda x: abs(x[0] - target))
        return closest_codes

    import re as _re_tlK
    def _parse_tl_code_k(c):
        if not c or c == '—':
            return ('—', '#e5e7eb', '#9ca3af')
        cu = c.upper().strip()
        if 'BR' in cu: return ('TO', '#dc2626', '#fff')
        if _re_tlK.match(r'^3', cu) and cu != '0/3': return ('3PT', '#1a6b3c', '#fff')
        if _re_tlK.match(r'^2', cu): return ('2PT', '#185FA5', '#fff')
        if cu.startswith('0/3'): return ('0/3', '#e5e7eb', '#6b7280')
        if cu.startswith('0/2') or cu.startswith('0D'): return ('0/2', '#e5e7eb', '#6b7280')
        ft_m = _re_tlK.search(r'(\d+)/(\d+)WL?', cu)
        if ft_m:
            made_f, tot_f = int(ft_m.group(1)), int(ft_m.group(2))
            ft_lbl = f'{made_f}/{tot_f} FT'
            ft_bg = '#1a6b3c' if made_f == tot_f and made_f > 0 else ('#dc2626' if made_f == 0 else '#b45309')
            return (ft_lbl, ft_bg, '#fff')
        if cu.startswith('F'): return ('F', '#d97706', '#fff')
        if 'PRZ' in cu: return ('STL', '#7c3aed', '#fff')
        if cu == 'P': return ('P', '#e5e7eb', '#9ca3af')
        return (c[:6] if len(c) > 6 else c, '#eff0f6', '#374151')

    def _timeline_html_k(codes):
        items = [('T.O.', '#3b82f6', '#fff', True)]
        for c in (codes if codes else []):
            lbl, bg, fg = _parse_tl_code_k(c)
            items.append((lbl, bg, fg, False))
        while len(items) < 6:
            items.append(('—', '#e5e7eb', '#9ca3af', False))
        html = ('<div style="position:relative;display:flex;align-items:center;padding:2px 0">'
                '<div style="position:absolute;top:11px;left:11px;right:11px;height:1.5px;background:#e8ecf3;z-index:0"></div>')
        for lbl, bg, fg, is_to in items:
            fs = '6.5px' if len(lbl) > 5 else ('7.5px' if len(lbl) > 3 else '9px')
            if is_to:
                dot_css = f'background:transparent;border:1.5px dashed {bg};color:{bg}'
            elif bg in ('#e5e7eb', '#eff0f6'):
                dot_css = f'background:{bg};border:1.5px solid #d1d5db;color:{fg}'
            else:
                dot_css = f'background:{bg};border:1.5px solid {bg};color:{fg}'
            html += (f'<div style="flex:1;display:flex;justify-content:center;position:relative;z-index:1">'
                     f'<div style="width:22px;height:22px;border-radius:50%;{dot_css};display:flex;align-items:center;'
                     f'justify-content:center;font-size:{fs};font-weight:800;line-height:1;text-align:center">{lbl}</div>'
                     f'</div>')
        html += '</div>'
        return html

    # Buduj panel dla danej drużyny (sidx=0 GTK akcje, sidx=1 OPP akcje)
    def _build_km_panel(sidx, sign, gtk_short, opp_short):
        all_tos_k = sorted((timeout_rows or []),
                            key=lambda r: (r.get("kwarta",1), -(r.get("czas_sek",0) or 0)))
        gtk_q_cnt = {}; opp_q_cnt = {}
        rows_html_x = ""
        for to in all_tos_k:
            druz = to.get("druzyna","gtk"); qn = int(to.get("kwarta",1)); cs = int(to.get("czas_sek",0) or 0)
            if druz == "gtk":
                sidx_own = 0
                idx_own  = gtk_q_cnt.get(qn, 0); gtk_q_cnt[qn] = idx_own + 1
                who_lbl   = gtk_short; who_col = "#1a6b3c"; who_bg = "#e8f5e9"
            else:
                sidx_own = 1
                idx_own  = opp_q_cnt.get(qn, 0); opp_q_cnt[qn] = idx_own + 1
                who_lbl   = opp_short; who_col = "#8b1a1a"; who_bg = "#ffebee"
            codes = _get_codes_k(sidx_own, sidx, qn, idx_own)
            _qs_g  = next((r for r in all_stats if r["druzyna"]=="gtk" and r["kwarta"]==qn), {})
            _qs_o  = next((r for r in all_stats if r["druzyna"]=="opp" and r["kwarta"]==qn), {})
            pts_g = int(_qs_g.get("pts",0) or 0); pts_o = int(_qs_o.get("pts",0) or 0)
            diff = (pts_g - pts_o) * sign
            dc = "#1a6b3c" if diff > 0 else ("#8b1a1a" if diff < 0 else "#888")
            ds = (f"+{diff}" if diff > 0 else str(diff))
            rows_html_x += (
                f'<tr style="border-bottom:0.5px solid #f0f2f6">'
                f'<td style="padding:6px 8px;vertical-align:top;width:62px">'
                f'<div style="font-size:10px;font-weight:600;color:#1a2b4a">{qn}Q</div>'
                f'<div style="font-size:9px;color:#888">{_fmt_to_time(cs)}</div>'
                f'<span style="display:inline-block;margin-top:3px;font-size:7.5px;font-weight:700;color:{who_col};'
                f'background:{who_bg};border-radius:3px;padding:1px 5px;white-space:nowrap">{who_lbl}</span>'
                f'</td>'
                f'<td style="padding:4px 6px;vertical-align:middle;min-width:0">{_timeline_html_k(codes)}</td>'
                f'<td style="padding:6px 6px;vertical-align:top;text-align:right;width:32px;font-size:11px;font-weight:700;color:{dc}">{ds}</td>'
                f'</tr>'
            )
        return rows_html_x or '<tr><td colspan="3" style="padding:12px;text-align:center;color:#aaa;font-size:9px">Brak timeoutów</td></tr>'

    _gtk_short = gtk_name.split()[0] if gtk_name else "GTK"
    _opp_short = name_opp.split()[0] if name_opp else "OPP"
    _km_rows_g = _build_km_panel(sidx=0, sign=1,  gtk_short=_gtk_short, opp_short=_opp_short)
    _km_rows_o = _build_km_panel(sidx=1, sign=-1, gtk_short=_gtk_short, opp_short=_opp_short)

    _km_hdr_style = "padding:4px 8px;font-size:8px;color:#bbb;text-transform:uppercase;letter-spacing:.4px"
    _key_moments_html = f"""
<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
  <div style="border:0.5px solid #e8ecf3;border-radius:6px;overflow:hidden;background:#fff">
    <div style="padding:8px 12px 6px;border-bottom:0.5px solid #e8ecf3">
      <span style="font-size:11px;font-weight:600;color:#1a6b3c">● {gtk_name}</span>
    </div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#fafbfd">
        <th style="{_km_hdr_style};text-align:left;width:62px">Q / MIN</th>
        <th style="{_km_hdr_style};text-align:left">Akcja</th>
        <th style="{_km_hdr_style};text-align:right;width:32px">±</th>
      </tr></thead>
      <tbody>{_km_rows_g}</tbody>
    </table>
  </div>
  <div style="border:0.5px solid #e8ecf3;border-radius:6px;overflow:hidden;background:#fff">
    <div style="padding:8px 12px 6px;border-bottom:0.5px solid #e8ecf3">
      <span style="font-size:11px;font-weight:600;color:#8b1a1a">● {name_opp}</span>
    </div>
    <table style="width:100%;border-collapse:collapse">
      <thead><tr style="background:#fafbfd">
        <th style="{_km_hdr_style};text-align:left;width:62px">Q / MIN</th>
        <th style="{_km_hdr_style};text-align:left">Akcja</th>
        <th style="{_km_hdr_style};text-align:right;width:32px">±</th>
      </tr></thead>
      <tbody>{_km_rows_o}</tbody>
    </table>
  </div>
</div>"""

    _przebieg_section = f"""
<div class="section" style="margin-top:8px">
  <h3>Przebieg meczu — kwartami i po timeoutach</h3>
  {_momentum_html}
  {_key_moments_html}
</div>"""

    # ══════════════════════════════════════════════════════════════════════════
    # SHOOTING CHART — 2 boiska atak (GTK vs OPP), bez tabeli zawodników
    # ══════════════════════════════════════════════════════════════════════════
    _svg_gtk_atk = _build_full_court_svg(_mr_zones_gtk, "all") if _mr_zones_gtk else '<div style="text-align:center;color:#aaa;padding:30px;font-size:9px">Brak danych stref</div>'
    _svg_opp_atk = _build_full_court_svg(_mr_zones_opp, "all") if _mr_zones_opp else '<div style="text-align:center;color:#aaa;padding:30px;font-size:9px">Brak danych stref</div>'

    _legend_items = [("#90c8e8","0–25%"),("#7ecb8f","26–49%"),("#2eab5f","50–79%"),("#e03030","≥80%")]
    _legend_html = "".join(
        f'<span style="display:inline-flex;align-items:center;gap:3px;font-size:8.5px">'
        f'<span style="width:18px;height:10px;background:{bg};border-radius:2px;display:inline-block;box-shadow:0 1px 1px rgba(0,0,0,.18)"></span>'
        f'<span style="color:#555;font-weight:700">{lbl}</span></span>'
        for bg, lbl in _legend_items
    )

    _shoot_section_html = f"""
<div class="section" style="margin-top:10px;page-break-before:always">
  <h3>Shooting Chart — porównanie stref ataku (zespołowo)</h3>
  <div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;align-items:center;margin-bottom:6px">
    {_legend_html}
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">
    <div style="text-align:center">
      <div style="font-size:9px;font-weight:700;color:#1a6b3c;text-transform:uppercase;letter-spacing:.5px;margin-bottom:3px">{gtk_name} — atak</div>
      <div style="border:1px solid #e8ecf3;border-radius:6px;padding:6px;background:#fff">{_svg_gtk_atk}</div>
    </div>
    <div style="text-align:center">
      <div style="font-size:9px;font-weight:700;color:#8b1a1a;text-transform:uppercase;letter-spacing:.5px;margin-bottom:3px">{name_opp} — atak</div>
      <div style="border:1px solid #e8ecf3;border-radius:6px;padding:6px;background:#fff">{_svg_opp_atk}</div>
    </div>
  </div>
  <div style="font-size:8px;color:#aaa;margin-top:4px;text-align:center">
    Liczby M/A w strefach to sumy z całego meczu. Kolory wg skuteczności FG%. Tylko dane zespołowe (bez statystyk indywidualnych).
  </div>
</div>"""

    html = f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<style>
  *{{box-sizing:border-box;margin:0;padding:0}}
  @page{{size:297mm 210mm;margin:1cm 1.2cm}}
  body{{font-family:Arial,sans-serif;font-size:11px;color:#222;background:#fff;width:100%}}
  .page{{width:100%;padding:0}}
  h3{{font-size:10px;text-transform:uppercase;letter-spacing:.5px;margin:0 0 5px;font-weight:700}}
  .hero{{background:#1a2b4a;padding:11px 18px;border-radius:6px;margin-bottom:10px;display:flex;justify-content:space-between;align-items:center}}
  .hero h2{{font-size:16px;font-weight:700;color:#fff;margin-bottom:2px}}
  .hero .meta{{font-size:9px;color:#a8c4e0}}
  .score{{font-size:30px;font-weight:700;letter-spacing:3px;color:#EF9F27}}
  .winner{{font-size:11px;font-weight:700;color:#5DCAA5}}
  .two-col{{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:10px}}
  .section{{margin-bottom:10px}}
  table{{width:100%;border-collapse:collapse;font-size:9.5px;margin-bottom:0}}
  th{{padding:5px 6px;color:#fff;font-size:8.5px;text-align:center}}
  th.left{{text-align:left}}
  td{{padding:4px 6px;border-bottom:1px solid #f0f0f0;text-align:center}}
  td.left{{text-align:left;font-weight:700}}
  tr.sum td{{font-weight:700}}
  .sep{{height:1px;background:#eee;margin:8px 0}}
  .kpi-header{{text-align:center;margin-bottom:5px}}
  .kpi-header-title{{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.5px}}
  .kpi-grid{{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-bottom:7px}}
  .kpi-box{{background:#f5f8ff;border-radius:4px;padding:5px 4px;text-align:center}}
  .kpi-val{{font-size:13px;font-weight:700;color:#1a2b4a}}
  .kpi-lbl{{font-size:7px;color:#888;text-transform:uppercase;line-height:1.2}}
  .kpi-box.kpi-net{{background:#e8f0fb;border:1px solid #c5d5f5}}
  .kpi-box.kpi-net .kpi-val{{color:#534AB7;font-size:12px;line-height:1.4}}
  .kpi-box.kpi-net .kpi-lbl{{color:#534AB7;font-weight:700}}
  .kpi-sub{{font-size:7px;color:#888;font-weight:400;display:block;margin-top:2px}}
  .net-pos{{color:#1a6b3c;font-weight:700}}
  .net-neg{{color:#8b1a1a;font-weight:700}}
  @media print{{body{{-webkit-print-color-adjust:exact;print-color-adjust:exact}}}}
</style>
</head><body>
<div class="page">

<!-- HERO -->
<div class="hero">
  <div>
    <h2>{gtk_name} vs {name_opp}</h2>
    <div class="meta">Sezon {m['sezon']} · {dt} · Basket Kołcz Analytics</div>
  </div>
  <div class="score">{m['wynik_gtk']} : {m['wynik_opp']}</div>
  <div class="winner">{'✓ ' if gtk_won else ''}{winner}</div>
</div>

<!-- KPI — dwie kolumny -->
<div class="two-col" style="margin-bottom:6px">
  <div>
    <div class="kpi-header"><div class="kpi-header-title" style="color:#1a6b3c">{gtk_name} — metryki kluczowe</div></div>
    <div class="kpi-grid" style="grid-template-columns:repeat(5,1fr);margin-bottom:4px">
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('pts',0)}</div><div class="kpi-lbl">Punkty</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('oreb',0)}&thinsp;/&thinsp;{suma_gtk.get('dreb',0)}</div><div class="kpi-lbl">Zb Off/Def</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('ast',0)}</div><div class="kpi-lbl">Asysty</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('stl',0)}</div><div class="kpi-lbl">Przechwyty</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('br',0)}</div><div class="kpi-lbl">Straty</div></div>
    </div>
    <div class="kpi-grid" style="grid-template-columns:repeat(5,1fr)">
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('d2m',0)}/{suma_gtk.get('d2a',0)}</div><div class="kpi-lbl">Dobitki M/A</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('przerw',0)}</div><div class="kpi-lbl">Przerwania</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_gtk.get('fd',0)}</div><div class="kpi-lbl">Faule wym.</div></div>
      <div class="kpi-box"><div class="kpi-val">{kpi_gtk['ppp']}</div><div class="kpi-lbl">PPP</div></div>
      <div class="kpi-box kpi-net"><div class="kpi-val">{float(kpi_gtk['ortg'])-float(kpi_opp['ortg']):+.1f}</div><div class="kpi-lbl">NETrtg</div></div>
    </div>
  </div>
  <div>
    <div class="kpi-header"><div class="kpi-header-title" style="color:#8b1a1a">{name_opp} — metryki kluczowe</div></div>
    <div class="kpi-grid" style="grid-template-columns:repeat(5,1fr);margin-bottom:4px">
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('pts',0)}</div><div class="kpi-lbl">Punkty</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('oreb',0)}&thinsp;/&thinsp;{suma_opp.get('dreb',0)}</div><div class="kpi-lbl">Zb Off/Def</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('ast',0)}</div><div class="kpi-lbl">Asysty</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('stl',0)}</div><div class="kpi-lbl">Przechwyty</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('br',0)}</div><div class="kpi-lbl">Straty</div></div>
    </div>
    <div class="kpi-grid" style="grid-template-columns:repeat(5,1fr)">
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('d2m',0)}/{suma_opp.get('d2a',0)}</div><div class="kpi-lbl">Dobitki M/A</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('przerw',0)}</div><div class="kpi-lbl">Przerwania</div></div>
      <div class="kpi-box"><div class="kpi-val">{suma_opp.get('fd',0)}</div><div class="kpi-lbl">Faule wym.</div></div>
      <div class="kpi-box"><div class="kpi-val">{kpi_opp['ppp']}</div><div class="kpi-lbl">PPP</div></div>
      <div class="kpi-box kpi-net"><div class="kpi-val">{float(kpi_opp['ortg'])-float(kpi_gtk['ortg']):+.1f}</div><div class="kpi-lbl">NETrtg</div></div>
    </div>
  </div>
</div>

<!-- PORÓWNANIE PASKAMI -->
{cmp_section}

<!-- PER KWARTA — dwie kolumny -->
<div class="two-col">
  <div class="section">
    <h3 style="color:#1a6b3c">{gtk_name} — per kwarta</h3>
    <table>
      <thead><tr>
        <th style="background:#1a2b4a" class="left">Q</th>
        <th style="background:#1a2b4a">PKT</th>
        <th style="background:#1a2b4a">2PM/A</th>
        <th style="background:#1a2b4a">3PM/A</th>
        <th style="background:#1a2b4a">FTM/A</th>
        <th style="background:#1a2b4a">TO</th>
        <th style="background:#1a2b4a">FG%</th>
        <th style="background:#1a2b4a">eFG%</th>
        <th style="background:#534AB7">NetRtg</th>
      </tr></thead>
      <tbody>
        {q_row('gtk',1,'1Q','opp')}{q_row('gtk',2,'2Q','opp')}{q_row('gtk',3,'3Q','opp')}{q_row('gtk',4,'4Q','opp')}
        <tr class="sum" style="background:#e8f0fb">
          <td class="left">SUMA</td>
          <td>{suma_gtk.get('pts',0)}</td>
          <td>{suma_gtk.get('p2m',0)}/{suma_gtk.get('p2a',0)}</td>
          <td>{suma_gtk.get('p3m',0)}/{suma_gtk.get('p3a',0)}</td>
          <td>{suma_gtk.get('ftm',0)}/{suma_gtk.get('fta',0)}</td>
          <td>{suma_gtk.get('br',0)}</td>
          <td>{kpi_gtk['fg']}</td>
          <td>{kpi_gtk['efg']}</td>
          <td class="{'net-pos' if float(kpi_gtk['ortg'])>float(kpi_opp['ortg']) else 'net-neg'}">{float(kpi_gtk['ortg'])-float(kpi_opp['ortg']):+.1f}</td>
        </tr>
      </tbody>
    </table>
  </div>
  <div class="section">
    <h3 style="color:#8b1a1a">{name_opp} — per kwarta</h3>
    <table>
      <thead><tr>
        <th style="background:#1a2b4a" class="left">Q</th>
        <th style="background:#1a2b4a">PKT</th>
        <th style="background:#1a2b4a">2PM/A</th>
        <th style="background:#1a2b4a">3PM/A</th>
        <th style="background:#1a2b4a">FTM/A</th>
        <th style="background:#1a2b4a">TO</th>
        <th style="background:#1a2b4a">FG%</th>
        <th style="background:#1a2b4a">eFG%</th>
        <th style="background:#534AB7">NetRtg</th>
      </tr></thead>
      <tbody>
        {q_row('opp',1,'1Q','gtk')}{q_row('opp',2,'2Q','gtk')}{q_row('opp',3,'3Q','gtk')}{q_row('opp',4,'4Q','gtk')}
        <tr class="sum" style="background:#fce8e8">
          <td class="left">SUMA</td>
          <td>{suma_opp.get('pts',0)}</td>
          <td>{suma_opp.get('p2m',0)}/{suma_opp.get('p2a',0)}</td>
          <td>{suma_opp.get('p3m',0)}/{suma_opp.get('p3a',0)}</td>
          <td>{suma_opp.get('ftm',0)}/{suma_opp.get('fta',0)}</td>
          <td>{suma_opp.get('br',0)}</td>
          <td>{kpi_opp['fg']}</td>
          <td>{kpi_opp['efg']}</td>
          <td class="{'net-pos' if float(kpi_opp['ortg'])>float(kpi_gtk['ortg']) else 'net-neg'}">{float(kpi_opp['ortg'])-float(kpi_gtk['ortg']):+.1f}</td>
        </tr>
      </tbody>
    </table>
  </div>
</div>

<div class="sep"></div>

<!-- ZAWODNICY -->
<div class="section">
  <h3 style="color:#1a6b3c">{gtk_name} — Zawodnicy</h3>
  <table style="table-layout:fixed;width:100%">
    <thead>
      <tr style="background:#1a2b4a;color:#fff;font-size:7.5px">
        <th style="text-align:left;padding:3px 4px" rowspan="2">Zawodnik</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">MIN<br>(szac.)</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">PTS</th>
        <th style="text-align:center;padding:3px 3px;background:#152236;color:rgba(255,255,255,.55)" colspan="2">2PT</th>
        <th style="text-align:center;padding:3px 3px;background:#152236;color:rgba(255,255,255,.55)" colspan="2">3PT</th>
        <th style="text-align:center;padding:3px 3px;background:#152236;color:rgba(255,255,255,.55)" colspan="2">FT</th>
        <th style="text-align:center;padding:3px 3px;background:#0d1b2e;color:rgba(255,255,255,.45)" colspan="3">ZB</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">AST</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">TO</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">STL</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">BLK</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">eFG%</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">TS%</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">USG%</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">FIN</th>
      </tr>
      <tr style="background:#1a2b4a;color:rgba(255,255,255,.7);font-size:7px">
        <th style="text-align:center;padding:2px 3px;background:#152236">M/A</th>
        <th style="text-align:center;padding:2px 3px;background:#152236">%</th>
        <th style="text-align:center;padding:2px 3px;background:#152236">M/A</th>
        <th style="text-align:center;padding:2px 3px;background:#152236">%</th>
        <th style="text-align:center;padding:2px 3px;background:#152236">M/A</th>
        <th style="text-align:center;padding:2px 3px;background:#152236">%</th>
        <th style="text-align:center;padding:2px 3px;background:#0d1b2e">A</th>
        <th style="text-align:center;padding:2px 3px;background:#0d1b2e">O</th>
        <th style="text-align:center;padding:2px 3px;background:#0d1b2e">S</th>
      </tr>
    </thead>
    <tbody>{player_rows('gtk') or '<tr><td colspan="20" style="text-align:center;color:#aaa">Brak danych</td></tr>'}</tbody>
  </table>
</div>

<div class="sep"></div>

<!-- OPP ZAWODNICY -->
<div class="section">
  <h3 style="color:#8b1a1a">{name_opp} — Zawodnicy</h3>
  <table style="table-layout:fixed;width:100%">
    <thead>
      <tr style="background:#6b1a1a;color:#fff;font-size:7.5px">
        <th style="text-align:left;padding:3px 4px" rowspan="2">Zawodnik</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">MIN<br>(szac.)</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">PTS</th>
        <th style="text-align:center;padding:3px 3px;background:#501212;color:rgba(255,255,255,.55)" colspan="2">2PT</th>
        <th style="text-align:center;padding:3px 3px;background:#501212;color:rgba(255,255,255,.55)" colspan="2">3PT</th>
        <th style="text-align:center;padding:3px 3px;background:#501212;color:rgba(255,255,255,.55)" colspan="2">FT</th>
        <th style="text-align:center;padding:3px 3px;background:#3d0d0d;color:rgba(255,255,255,.45)" colspan="3">ZB</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">AST</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">TO</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">STL</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">BLK</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">eFG%</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">TS%</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">USG%</th>
        <th style="text-align:center;padding:3px 3px" rowspan="2">FIN</th>
      </tr>
      <tr style="background:#6b1a1a;color:rgba(255,255,255,.7);font-size:7px">
        <th style="text-align:center;padding:2px 3px;background:#501212">M/A</th>
        <th style="text-align:center;padding:2px 3px;background:#501212">%</th>
        <th style="text-align:center;padding:2px 3px;background:#501212">M/A</th>
        <th style="text-align:center;padding:2px 3px;background:#501212">%</th>
        <th style="text-align:center;padding:2px 3px;background:#501212">M/A</th>
        <th style="text-align:center;padding:2px 3px;background:#501212">%</th>
        <th style="text-align:center;padding:2px 3px;background:#3d0d0d">A</th>
        <th style="text-align:center;padding:2px 3px;background:#3d0d0d">O</th>
        <th style="text-align:center;padding:2px 3px;background:#3d0d0d">S</th>
      </tr>
    </thead>
    <tbody>{player_rows('opp') or '<tr><td colspan="20" style="text-align:center;color:#aaa">Brak danych</td></tr>'}</tbody>
  </table>
</div>

<div class="sep"></div>

<!-- SCORE FLOW — wykres SVG kumulacyjnych punktów + timeouty -->
{_scoreflow_section}

<div class="sep"></div>

<!-- PRZEBIEG (momentum + key_moments) -->
{_przebieg_section}

<div class="sep"></div>

<!-- CLUTCH -->
{clutch_section}

<!-- TIMING AKCJI -->
<div class="section">
  <h3>Timing Akcji — skuteczność rzutów w czasie posiadania</h3>
  <table style="width:100%">
    <thead>
      <tr>
        <th rowspan="2" style="background:#1a2b4a;text-align:left;width:50px">Czas</th>
        <th colspan="8" style="background:#1a6b3c">{gtk_name}</th>
        <th style="background:#fff;width:8px"></th>
        <th colspan="8" style="background:#8b1a1a">{name_opp}</th>
      </tr>
      <tr>
        <th style="background:#085041">2PT✓</th><th style="background:#085041">3PT✓</th><th style="background:#085041">FT</th>
        <th style="background:#5a1515">2PT✗</th><th style="background:#5a1515">3PT✗</th><th style="background:#5a1515">BR</th>
        <th style="background:#1a2b4a">RAZEM</th><th style="background:#1a2b4a">EFG%</th>
        <th style="background:#fff;width:8px"></th>
        <th style="background:#085041">2PT✓</th><th style="background:#085041">3PT✓</th><th style="background:#085041">FT</th>
        <th style="background:#5a1515">2PT✗</th><th style="background:#5a1515">3PT✗</th><th style="background:#5a1515">BR</th>
        <th style="background:#1a2b4a">RAZEM</th><th style="background:#1a2b4a">EFG%</th>
      </tr>
    </thead>
    <tbody>{timing_rows()}</tbody>
  </table>
</div>

<!-- TIMING ZONES — 4 strefy GTK vs OPP -->
<div class="section" style="margin-top:8px">
  <h3>Timing — strefy ataku (GTK vs OPP)</h3>
  <table style="width:100%">
    <thead>
      <tr>
        <th rowspan="2" style="background:#1a2b4a;text-align:left;padding:3px 6px;width:55px">Strefa</th>
        <th rowspan="2" style="background:#1a2b4a;text-align:left;padding:3px 6px;width:70px">Typ gry</th>
        <th colspan="3" style="background:#1a6b3c">{gtk_name}</th>
        <th style="background:#fff;width:8px"></th>
        <th colspan="3" style="background:#8b1a1a">{name_opp}</th>
      </tr>
      <tr>
        <th style="background:#085041">FG M/A</th>
        <th style="background:#085041">eFG%</th>
        <th style="background:#085041">BR</th>
        <th style="background:#fff;width:8px"></th>
        <th style="background:#5a1515">FG M/A</th>
        <th style="background:#5a1515">eFG%</th>
        <th style="background:#5a1515">BR</th>
      </tr>
    </thead>
    <tbody>{timing_zone_rows()}</tbody>
  </table>
</div>

{ft_br_html()}

<div style="margin-top:10px;text-align:center;font-size:7.5px;color:#aaa;border-top:1px solid #eee;padding-top:5px">
  Basket Kołcz Analytics · {gtk_name} vs {name_opp} · {dt}
</div>

</div>
</body></html>"""

    # Wstaw piątki przed footer + Shooting Chart side-by-side po piątkach
    _post_lineup = (lineup_html or "") + _shoot_section_html
    if _post_lineup.strip():
        html = html.replace(
            '  Basket Kołcz Analytics · ' + gtk_name + ' vs ' + name_opp + ' · ' + dt,
            _post_lineup + '\n<div style="text-align:center;font-size:7.5px;color:#aaa;border-top:1px solid #eee;padding-top:5px">\n  Basket Kołcz Analytics · ' + gtk_name + ' vs ' + name_opp + ' · ' + dt
        )

    html_print = html.replace(
        "</body></html>",
        "<script>window.onload=function(){window.print();}</script></body></html>"
    )
    return Response(html_print, mimetype="text/html")


# ══════════════════════════════════════════════════════════════════════════════
# SZABLONY (identyczne jak w app_v2)
# ══════════════════════════════════════════════════════════════════════════════


@app.route("/template/sklad")
@login_required
def template_sklad():
    """Szablon do importu składu drużyny.

    Układ kolumn:
        LP | NAZWISKO | IMIE | NR LIC. STAŁEJ | DATA UR. | WZROST | POZYCJA

    UWAGA: Pozycja to pole tekstowe (dowolna wartość). Status usunięty —
    nowi zawodnicy są domyślnie aktywni.
    """
    from io import BytesIO
    from flask import send_file
    HEADERS = ["LP", "NAZWISKO", "IMIE", "NR LIC. STAŁEJ", "DATA UR.", "WZROST", "POZYCJA"]

    if request.args.get("fmt") == "csv":
        csv_rows = [",".join(HEADERS)]
        for i in range(1, 21):
            csv_rows.append(f"{i},,,,,,")
        return send_file(
            BytesIO("\n".join(csv_rows).encode("utf-8")),
            mimetype="text/csv",
            as_attachment=True,
            download_name="sklad_druzyny.csv"
        )

    # XLSX — generujemy dynamicznie
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Skład drużyny"

    hdr_font = Font(bold=True, color="FFFFFF", size=11)
    hdr_fill = PatternFill(start_color="1A2B4A", end_color="1A2B4A", fill_type="solid")
    hdr_align = Alignment(horizontal="center", vertical="center")
    thin = Side(border_style="thin", color="DDDDDD")
    border = Border(left=thin, right=thin, top=thin, bottom=thin)

    # Nagłówek
    for col, label in enumerate(HEADERS, 1):
        cell = ws.cell(row=1, column=col, value=label)
        cell.font = hdr_font
        cell.fill = hdr_fill
        cell.alignment = hdr_align
        cell.border = border

    # Szerokości kolumn: LP, NAZWISKO, IMIE, NR LIC.STAŁEJ, DATA UR., WZROST, POZYCJA
    widths = [5, 22, 16, 18, 15, 10, 22]
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.row_dimensions[1].height = 26

    # 20 pustych wierszy + LP
    cell_align = Alignment(horizontal="left", vertical="center")
    lp_align   = Alignment(horizontal="center", vertical="center")
    num_align  = Alignment(horizontal="center", vertical="center")
    for i in range(2, 22):
        cell_lp = ws.cell(row=i, column=1, value=i-1)
        cell_lp.alignment = lp_align
        cell_lp.border = border
        for col in range(2, 8):
            c = ws.cell(row=i, column=col)
            c.border = border
            c.alignment = cell_align
        # Format daty dla kol. 5 (DATA UR.)
        ws.cell(row=i, column=5).number_format = "DD.MM.YYYY"
        # Wzrost — wyśrodkowany (kol 6)
        ws.cell(row=i, column=6).alignment = num_align
        ws.cell(row=i, column=6).number_format = "0"

    # Brak walidacji pozycji — dowolny tekst

    # Instrukcja w dodatkowej zakładce
    ws_help = wb.create_sheet("Instrukcja")
    ws_help.column_dimensions["A"].width = 95
    ws_help["A1"] = "Instrukcja wypełniania szablonu składu drużyny"
    ws_help["A1"].font = Font(bold=True, size=14, color="1A2B4A")
    rows_help = [
        "",
        "Wymagane: NAZWISKO, IMIE",
        "Opcjonalne: NR LIC. STAŁEJ, DATA UR. (DD.MM.YYYY lub YYYY-MM-DD), WZROST (cm), POZYCJA (dowolny tekst)",
        "",
        "DATA UR. i NR LIC. STAŁEJ służą do unikalnej identyfikacji zawodnika",
        "między klubami i sezonami (hierarchia synchronizacji).",
        "",
        "Po wgraniu pliku w panelu drużyny zawodnicy zostaną dodani z pełną kartoteką globalną.",
        "Jeśli osoba o tym samym (Imię, Nazwisko, Data urodzenia) już istnieje — system użyje",
        "istniejącego globalnego profilu zamiast tworzyć duplikat.",
        "",
        "W systemie drużyny: filtracja po nazwisku, wyświetlanie jako 'Imię Nazwisko'.",
    ]
    for i, line in enumerate(rows_help, 2):
        ws_help.cell(row=i, column=1, value=line)

    out = BytesIO()
    wb.save(out)
    out.seek(0)
    return send_file(out,
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                     as_attachment=True,
                     download_name="sklad_druzyny.xlsx")


