def get_portal_lang():
    """Zwraca aktualny język portalu z cookie. Default 'pl'."""
    return request.cookies.get('portal_lang', 'pl')

def TP(key, lang=None):
    """Translate Portal — pobiera tłumaczenie wg klucza.
    Gdy lang=None pobiera aktualny język z cookie.
    Gdy brak klucza w słowniku — zwraca klucz."""
    if lang is None:
        try: lang = get_portal_lang()
        except: lang = 'pl'
    entry = PORTAL_TRANSLATIONS.get(key)
    if not entry:
        return key  # fallback: zwraca klucz, łatwo wykryć brakujące tłumaczenia
    return entry.get(lang, entry.get('pl', key))


def fmt_date_portal(d, lang=None):
    """Format daty zgodny z językiem portalu.
    PL: DD.MM.YYYY | EN: MMM DD, YYYY (np. May 26, 2026).
    Akceptuje obiekt date/datetime lub string ISO (YYYY-MM-DD)."""
    if d is None:
        return ""
    if lang is None:
        try: lang = get_portal_lang()
        except: lang = 'pl'
    # parse string ISO
    if isinstance(d, str):
        try:
            from datetime import datetime
            d = datetime.strptime(d[:10], "%Y-%m-%d").date()
        except Exception:
            return d
    try:
        if lang == 'en':
            _months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]
            return f"{_months[d.month-1]} {d.day}, {d.year}"
        return d.strftime("%d.%m.%Y")
    except Exception:
        return str(d)


@app.route("/portal/set-lang", methods=["POST"])
def portal_set_lang():
    """Ustawia język portalu w cookie (365 dni)."""
    lang = (request.form.get("lang") or request.args.get("lang") or "pl").lower()
    if lang not in ("pl", "en"):
        lang = "pl"
    ref = request.referrer or url_for("portal")
    resp = redirect(ref)
    resp.set_cookie("portal_lang", lang, max_age=365*24*3600, path="/", samesite="Lax")
    return resp


def portal_lang_switcher_html(lang=None):
    """Renderuje przełącznik PL/EN dla desktop (dropdown w headerze).
    Wkleja się do topbara portalu."""
    if lang is None:
        try: lang = get_portal_lang()
        except: lang = 'pl'
    pl_active = (lang == 'pl')
    en_active = (lang == 'en')
    cur_flag = '🇵🇱' if pl_active else '🇬🇧'
    cur_lbl  = 'PL' if pl_active else 'EN'
    return f"""
<div class="lang-switcher" style="position:relative;display:inline-block;margin-left:auto">
  <button id="lang-toggle-btn" onclick="document.getElementById('lang-dd').classList.toggle('open')"
    style="background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.25);
    border-radius:6px;padding:6px 12px;font-size:12px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px">
    <span style="font-size:14px">{cur_flag}</span> {cur_lbl}
    <span style="font-size:8px;opacity:.7">▼</span>
  </button>
  <div id="lang-dd" style="display:none;position:absolute;top:calc(100% + 4px);right:0;
    background:#fff;border:1px solid #e0e0e0;border-radius:8px;
    box-shadow:0 4px 12px rgba(0,0,0,.15);min-width:140px;z-index:200;overflow:hidden">
    <form method="POST" action="/portal/set-lang" style="margin:0">
      <button name="lang" value="pl" type="submit"
        style="display:flex;align-items:center;gap:8px;width:100%;padding:8px 12px;background:{'#eef2fb' if pl_active else '#fff'};border:none;
        font-size:13px;font-weight:{'700' if pl_active else '500'};color:#1a2b4a;cursor:pointer;text-align:left">
        <span style="font-size:16px">🇵🇱</span> Polski {'✓' if pl_active else ''}
      </button>
    </form>
    <form method="POST" action="/portal/set-lang" style="margin:0;border-top:0.5px solid #f0f0f0">
      <button name="lang" value="en" type="submit"
        style="display:flex;align-items:center;gap:8px;width:100%;padding:8px 12px;background:{'#eef2fb' if en_active else '#fff'};border:none;
        font-size:13px;font-weight:{'700' if en_active else '500'};color:#1a2b4a;cursor:pointer;text-align:left">
        <span style="font-size:16px">🇬🇧</span> English {'✓' if en_active else ''}
      </button>
    </form>
  </div>
</div>
<style>
.lang-switcher #lang-dd.open {{ display:block !important; }}
.lang-switcher button:hover {{ background:rgba(255,255,255,.2) !important; }}
@media (max-width: 899px) {{
  .lang-switcher {{ display:none !important; }}  /* na mobile: w burger menu */
}}
</style>
<script>
// Zamknij dropdown przy kliknięciu poza nim
document.addEventListener('click', function(e) {{
  var btn = document.getElementById('lang-toggle-btn');
  var dd  = document.getElementById('lang-dd');
  if (!btn || !dd) return;
  if (!btn.contains(e.target) && !dd.contains(e.target)) {{
    dd.classList.remove('open');
  }}
}});
</script>
"""


def portal_lang_switcher_mobile_html(lang=None):
    """Renderuje przełącznik PL/EN dla mobile (toggle pills wewnątrz menu/sidebar)."""
    if lang is None:
        try: lang = get_portal_lang()
        except: lang = 'pl'
    pl_active = (lang == 'pl')
    en_active = (lang == 'en')
    return f"""
<div class="lang-switcher-mobile" style="padding:10px 14px;border-bottom:0.5px solid rgba(255,255,255,.1)">
  <div style="font-size:10px;color:rgba(255,255,255,.55);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">🌐 {TP('language', lang)}</div>
  <div style="display:flex;gap:6px">
    <form method="POST" action="/portal/set-lang" style="margin:0;flex:1">
      <button name="lang" value="pl" type="submit"
        style="width:100%;padding:7px 12px;border-radius:18px;
        background:{'#fff' if pl_active else 'rgba(255,255,255,.08)'};
        color:{'#1a2b4a' if pl_active else 'rgba(255,255,255,.7)'};
        border:1px solid {'#fff' if pl_active else 'rgba(255,255,255,.15)'};
        font-size:12px;font-weight:{'700' if pl_active else '500'};cursor:pointer">
        🇵🇱 PL
      </button>
    </form>
    <form method="POST" action="/portal/set-lang" style="margin:0;flex:1">
      <button name="lang" value="en" type="submit"
        style="width:100%;padding:7px 12px;border-radius:18px;
        background:{'#fff' if en_active else 'rgba(255,255,255,.08)'};
        color:{'#1a2b4a' if en_active else 'rgba(255,255,255,.7)'};
        border:1px solid {'#fff' if en_active else 'rgba(255,255,255,.15)'};
        font-size:12px;font-weight:{'700' if en_active else '500'};cursor:pointer">
        🇬🇧 EN
      </button>
    </form>
  </div>
</div>
<style>
@media (min-width: 900px) {{
  .lang-switcher-mobile {{ display:none !important; }}  /* na desktop: w headerze */
}}
</style>
"""


