        _br_gt = max(sum(_br_g.values()), 1); _br_ot = max(sum(_br_o.values()), 1)
        _br_mx = max(max(_br_g.values()), max(_br_o.values()), 1)
        def _br_row(bkt):
            gv=_br_g.get(bkt,0); ov=_br_o.get(bkt,0)
