def _koder_court_svg():
    """SVG z klikalnymi strefami boiska dla kodera v2 (FIBA, pelne boisko 490x880).
    Warstwy:
      1. tło
      2. linie boiska (pod strefami — granice stref nie są przykryte)
      3. wypełnienia stref (klikalne, bez obrysu)
      4. obrysy stref (pointer-events=none, na wierzchu linii boiska — zawsze widoczne)
    """
    fills_parts  = []
    stroke_parts = []
    labels_parts = []
    for zid, zd in _KODER_ZONES.items():
        shape = zd[0]
        pts   = zd[-1]
        name  = zd[-2]
        # Strefy niewidoczne podczas kodowania — czyste boisko
        # Klikalne area jest przezroczyste; delikatny hover daje feedback
        _cx = zd[-4]
        _cy = zd[-3]
        attrs_fill = (
            f'data-zone="{zid}" data-pts="{pts}" data-name="{name}" '
            f'data-cx="{_cx}" data-cy="{_cy}" '
            f'fill="transparent" stroke="none" class="kdr-zone"'
        )
        if shape == 'rect':
            _, rx, ry, rw, rh, _cx, _cy, _nm, _pts = zd
            fills_parts.append(
                f'<rect {attrs_fill} x="{rx}" y="{ry}" width="{rw}" height="{rh}"/>'
            )
        else:
            _, path_d, _cx, _cy, _nm, _pts = zd
            fills_parts.append(f'<path {attrs_fill} d="{path_d}"/>')
        # stroke_parts i labels_parts pozostają puste — brak siatki stref

    # Boisko poziome: SVG 490×880 obrócony 90° → wizualnie 880×490 (landscape)
    # Wrapper tworzy aspect-ratio 880:490 i ogranicza wysokość do ~100vh
    return (
        # Zewnętrzny kontener: ogranicza szerokość wg dostępnej wysokości ekranu
        '<div style="'
        'position:relative;'
        'width:min(100%, calc((100vh - 220px) * 880 / 490));'
        'overflow:hidden;border-radius:8px;">'
        # Wewnętrzny: padding-top = 490/880 * 100% = 55.68% tworzy aspect ratio
        '<div style="padding-top:55.68%;position:relative;">'
        # SVG: ustawiony absolutnie, obrócony 90° CCW
        # width=55.68% → po obróceniu staje się wysokością
        # height=179.59% → po obróceniu staje się szerokością (= szerokość kontenera)
        '<svg id="kdrSvg" viewBox="0 0 490 880" xmlns="http://www.w3.org/2000/svg"'
        ' style="'
        'position:absolute;'
        'width:55.68%;height:179.59%;'
        'left:50%;top:50%;'
        'transform:translate(-50%,-50%) rotate(90deg);'
        'cursor:crosshair;"'
        ' onclick="svgClick(event)">'
        '<style>'
        '.kdr-zone{cursor:crosshair;transition:fill .08s}'
        '.kdr-zone:hover{fill:rgba(26,43,74,.12)!important}'
        '.kdr-zone:active{fill:rgba(26,43,74,.25)!important}'
        '</style>'
        '<rect width="490" height="880" fill="#f7f3e8" rx="8"/>'
        + _KODER_COURT_LINES              # linie boiska — jedyna warstwa widoczna
        + '\n'.join(fills_parts)          # niewidoczne obszary klikalne (transparent)
        # stroke_parts i labels_parts usunięte — czyste boisko
        + '</svg>'
        + '</div></div>'
    )



def _build_v2_chart_svg(zone_data, side='all'):
    """Shooting chart v2: pelne boisko FIBA 490x880, 49 stref.
    zone_data: {zone_id: {"made": N, "att": N}}
    side: 'all'=koloruj wszystkie | 'atk'=1-25 | 'def'=26-49
    """
    def _fmt(n):
        n = float(n or 0)
        return str(int(n)) if n == int(n) else f"{n:.1f}"

    zone_els = []
    for zid, zd in _KODER_ZONES.items():
        shape = zd[0]
        cx    = zd[-4]
        cy    = zd[-3]
        name  = zd[-2]

        zdat = zone_data.get(zid, {})
        made = float(zdat.get("made", 0) or 0)
        att  = float(zdat.get("att",  0) or 0)
        pct  = made / att if att > 0 else None

        active = (side == 'all') or \
                 (side == 'atk' and 1  <= zid <= 25) or \
                 (side == 'def' and 26 <= zid <= 49)

        if active:
            fill, stroke_c, tcol = _zone_fill_color(pct if pct is not None else 0, att)
        else:
            fill, stroke_c, tcol = "rgba(215,222,232,0.20)", "rgba(155,165,180,0.30)", "#bbb"

        if shape == 'rect':
            _, rx, ry, rw, rh, _cx, _cy, _nm, _pts = zd
            shape_el = (f'<rect x="{rx}" y="{ry}" width="{rw}" height="{rh}"'
                        f' fill="{fill}" stroke="{stroke_c}" stroke-width="1"/>')
        else:
            _, path_d, _cx, _cy, _nm, _pts = zd
            shape_el = f'<path d="{path_d}" fill="{fill}" stroke="{stroke_c}" stroke-width="1"/>'

        pct_str = f"{pct*100:.0f}%" if pct is not None else "-"
        tooltip = f'<title>Z{zid} {name}: {_fmt(made)}/{_fmt(att)} ({pct_str})</title>'

        texts = ""
        if active and att > 0:
            ma_txt = f"{_fmt(made)}/{_fmt(att)}"
            texts = (
                f'<text x="{cx}" y="{cy-6}" text-anchor="middle" dominant-baseline="middle"'
                f' font-size="11" font-weight="800" font-family="Arial,sans-serif"'
                f' fill="{tcol}">{ma_txt}</text>'
                f'<text x="{cx}" y="{cy+7}" text-anchor="middle" dominant-baseline="middle"'
                f' font-size="9.5" font-weight="600" font-family="Arial,sans-serif"'
                f' fill="{tcol}">{pct_str}</text>'
            )

        zone_els.append(f'<g class="zg">{tooltip}{shape_el}{texts}</g>')

    return (
        '<svg viewBox="0 0 490 880" xmlns="http://www.w3.org/2000/svg"'
        ' style="width:100%;display:block;border-radius:8px;'
        'box-shadow:0 2px 8px rgba(0,0,0,.10)">'
        '<style>.zg text{pointer-events:none}</style>'
        '<rect width="490" height="880" fill="#f7f3e8" rx="8"/>'
        + "\n".join(zone_els)
        + _KODER_COURT_LINES
        + '</svg>'
    )

