@app.route("/api/koder/event", methods=["POST"])
@login_required
def api_koder_event_add():
    """Zapisz nowe zdarzenie w match_events."""
    import json as _j
    data     = request.get_json() or {}
    match_id = int(data.get("match_id") or 0)
    if not match_id:
        return _j.dumps({"ok": False, "error": "Brak match_id"}), 400

    kwarta    = int(data.get("kwarta") or 1)
    czas_sek  = float(data.get("czas_sek") or 0)
    druzyna   = ((data.get("druzyna") or "gtk").lower())[:10]
    nr_raw    = data.get("nr")
    nr        = int(nr_raw) if nr_raw not in (None, "") else None
    pid_raw   = data.get("player_id")
    player_id = int(pid_raw) if pid_raw else None
    etype     = ((data.get("event_type") or "").strip())[:30]
    result    = (data.get("result") or "").strip() or None
    if result:
        result = result[:10]
    zone_raw        = data.get("zone")
    zone            = int(zone_raw) if zone_raw is not None else None
    coord_x         = data.get("coord_x")
    coord_y         = data.get("coord_y")
    violation_type  = (data.get("violation_type") or "").strip()[:20] or None
    shot_clock_raw  = data.get("shot_clock_sek")
    shot_clock_sek  = float(shot_clock_raw) if shot_clock_raw is not None else None
    shot_type_raw   = (data.get("shot_type") or "").strip()[:20] or None

    if not etype:
        return _j.dumps({"ok": False, "error": "Brak event_type"}), 400

    db = get_db(); cur = db.cursor()
    cur.execute("""
        INSERT INTO match_events
            (match_id, kwarta, czas_sek, druzyna, nr, player_id,
             event_type, result, zone, coord_x, coord_y,
             violation_type, shot_clock_sek, shot_type)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
        RETURNING id, match_id, kwarta, czas_sek, druzyna, nr,
                  event_type, result, zone, violation_type,
                  shot_clock_sek, shot_type, created_at
    """, (match_id, kwarta, czas_sek, druzyna, nr, player_id,
          etype, result, zone, coord_x, coord_y,
          violation_type, shot_clock_sek, shot_type_raw))
    row = cur.fetchone()
    db.commit(); cur.close()
    return _j.dumps({"ok": True, "event": {
        "id":             row["id"],
        "kwarta":         row["kwarta"],
        "czas_sek":       float(row["czas_sek"]) if row["czas_sek"] is not None else None,
        "druzyna":        row["druzyna"],
        "nr":             row["nr"],
        "event_type":     row["event_type"],
        "result":         row["result"],
        "zone":           row["zone"],
        "violation_type": row["violation_type"],
        "created_at":     (row["created_at"].strftime("%H:%M:%S")
                           if row["created_at"] else ""),
    }})


@app.route("/api/teams/<int:team_id>/players")
@login_required
def api_team_players_koder(team_id):
    """Zwróć zawodników drużyny jako JSON [{nr, imie, nazwisko, id}] — dla formularza kodera."""
    import json as _j
    db = get_db(); cur = db.cursor()
    cur.execute("""
        SELECT id, numer AS nr, imie, nazwisko
        FROM players WHERE team_id=%s ORDER BY numer
    """, (team_id,))
    rows = cur.fetchall(); cur.close()
