import json as _json_ak


def _ak_ensure_tables():
    """Tworzy tabele akademii i seeduje lekcje jeśli puste."""
    try:
        db = get_db(); cur = db.cursor()
        cur.execute("""CREATE TABLE IF NOT EXISTS player_lessons (
            id             SERIAL PRIMARY KEY,
            title          VARCHAR(200) NOT NULL,
            category       VARCHAR(50)  DEFAULT 'taktyka',
            content        TEXT         DEFAULT '',
            video_url      VARCHAR(500) DEFAULT '',
            position_focus VARCHAR(20)  DEFAULT 'ALL',
            stat_trigger   VARCHAR(100) DEFAULT '',
            order_num      INT          DEFAULT 0,
            active         BOOLEAN      DEFAULT true,
            duration_min   INT          DEFAULT 5
        )""")
        cur.execute("""CREATE TABLE IF NOT EXISTS player_quiz_questions (
            id           SERIAL PRIMARY KEY,
            lesson_id    INT  REFERENCES player_lessons(id) ON DELETE CASCADE,
            question     TEXT NOT NULL,
            options_json TEXT NOT NULL,
            correct_idx  INT  NOT NULL DEFAULT 0,
            explanation  TEXT DEFAULT ''
        )""")
        cur.execute("""CREATE TABLE IF NOT EXISTS player_lesson_views (
            id        SERIAL PRIMARY KEY,
            player_id INT,
            lesson_id INT,
            viewed_at TIMESTAMP DEFAULT NOW(),
            UNIQUE(player_id, lesson_id)
        )""")
        cur.execute("""CREATE TABLE IF NOT EXISTS player_quiz_results (
            id           SERIAL PRIMARY KEY,
            player_id    INT,
            lesson_id    INT,
            score        INT DEFAULT 0,
            total        INT DEFAULT 0,
            completed_at TIMESTAMP DEFAULT NOW()
        )""")
        cur.execute("""CREATE TABLE IF NOT EXISTS player_development (
            player_id    INT PRIMARY KEY,
            identity     TEXT DEFAULT '',
            strengths    TEXT DEFAULT '[]',
            weaknesses   TEXT DEFAULT '[]',
            competencies TEXT DEFAULT '[]',
            process_goal TEXT DEFAULT '',
            goal_days    TEXT DEFAULT '[]',
            review_date  DATE,
            updated_at   TIMESTAMP DEFAULT NOW()
        )""")
        for _col_sql in [
            "ALTER TABLE player_quiz_questions ADD COLUMN IF NOT EXISTS question_type VARCHAR(20) DEFAULT 'abcd'",
            "ALTER TABLE player_quiz_questions ADD COLUMN IF NOT EXISTS answer_data TEXT DEFAULT ''",
            "ALTER TABLE player_quiz_results   ADD COLUMN IF NOT EXISTS answer_text TEXT DEFAULT ''",
            "ALTER TABLE player_lessons        ADD COLUMN IF NOT EXISTS images TEXT DEFAULT '[]'",
            "ALTER TABLE player_quiz_questions ADD COLUMN IF NOT EXISTS order_num INT DEFAULT 0",
            "ALTER TABLE player_lessons        ADD COLUMN IF NOT EXISTS attachments TEXT DEFAULT '[]'",
            "ALTER TABLE player_quiz_questions ADD COLUMN IF NOT EXISTS active BOOLEAN DEFAULT true",
        ]:
            try: cur.execute(_col_sql)
            except Exception:
                try: db.rollback()
                except: pass
        cur.execute("SELECT COUNT(*) as n FROM player_lessons")
        if cur.fetchone()["n"] == 0:
            _ak_seed(cur)
        db.commit(); cur.close()
    except Exception:
        try: db.rollback()
        except: pass


