            '  else{d.classList.remove("open");if(b)b.textContent="Edytuj lekcję";}'
            '}'
            'function akSaveLesson(e){'
            '  e.preventDefault();'
            '  var form=document.getElementById("ak-edit-form");'
            '  var data=new FormData(form);'
