@app.route("/akademia/api/lekcja/edit", methods=["POST"])
@login_required
def api_akademia_lekcja_edit():
    import json as _j
    try:
        lid = int(request.form.get("lid") or 0)
        t   = (request.form.get("title") or "").strip()
        co  = (request.form.get("content") or "").strip()
        if not lid or not t or not co:
            return _j.dumps({"ok": False, "error": "Brak danych"}), 400
        cat = (request.form.get("category") or "taktyka").strip()
        vu  = (request.form.get("video_url") or "").strip()
        dm  = int(request.form.get("duration_min") or 5)
        ak  = request.form.get("aktywny") == "1"
        db  = get_db(); cur = db.cursor()
        cur.execute(
            "UPDATE player_lessons SET title=%s, category=%s, content=%s, "
            "video_url=%s, duration_min=%s, active=%s WHERE id=%s",
            (t, cat, co, vu or None, dm, ak, lid))
        db.commit(); cur.close()
        return _j.dumps({"ok": True})
    except Exception as ex:
        try: get_db().rollback()
        except: pass
        return _j.dumps({"ok": False, "error": str(ex)}), 500


