def _yt_embed_url(url):
    """Zwraca URL embed YouTube lub pusty string jeśli nie rozpoznano."""
    import re
    if not url:
        return ""
    for pat in (r'youtu\.be/([A-Za-z0-9_-]{11})',
                r'[?&]v=([A-Za-z0-9_-]{11})',
                r'youtube\.com/embed/([A-Za-z0-9_-]{11})'):
        m = re.search(pat, url)
        if m:
            return "https://www.youtube.com/embed/" + m.group(1)
    return ""


