import os as _os_ak
import uuid as _uuid_ak

def _ak_render_images(images_json):
    """Renderuje galerię zdjęć lekcji (portal + edytor)."""
    try:
        imgs = _json_ak.loads(images_json or "[]") or []
    except Exception:
        imgs = []
    if not imgs:
        return ""
    grid = ""
    for url in imgs:
        grid += ('<div style="position:relative;overflow:hidden;border-radius:10px;'
                 'background:rgba(255,255,255,.04)">'
                 '<img src="' + str(url) + '" '
                 'style="width:100%;height:160px;object-fit:cover;display:block" loading="lazy">'
                 '</div>')
    return ('<div style="margin:14px 0">'
            '<div style="font-size:.63rem;font-weight:800;text-transform:uppercase;'
            'letter-spacing:.08em;color:var(--mut);margin-bottom:8px">Galeria zdjęć</div>'
            '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px">'
            + grid + '</div></div>')


# ── Upload zdjęcia ─────────────────────────────────────────────────
@app.route("/akademia/upload-img", methods=["POST"])
@login_required
def akademia_upload_img():
    f = request.files.get("file")
    if not f or not f.filename:
        return _json_ak.dumps({"ok": False, "error": "Brak pliku"}), 400
    ext = (f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else "")
    if ext not in ("jpg", "jpeg", "png", "gif", "webp"):
        return _json_ak.dumps({"ok": False, "error": "Dozwolone: jpg, png, gif, webp"}), 400
    upload_dir = _os_ak.path.join("static", "uploads", "akademia")
    _os_ak.makedirs(upload_dir, exist_ok=True)
    fname = _uuid_ak.uuid4().hex[:12] + "." + ext
    f.save(_os_ak.path.join(upload_dir, fname))
    return _json_ak.dumps({"ok": True, "url": "/static/uploads/akademia/" + fname})


# ── Upload pliku (PDF, DOCX…) ──────────────────────────────────────
@app.route("/akademia/upload-file", methods=["POST"])
@login_required
def akademia_upload_file():
    f = request.files.get("file")
    if not f or not f.filename:
        return _json_ak.dumps({"ok": False, "error": "Brak pliku"}), 400
    ext = (f.filename.rsplit(".", 1)[-1].lower() if "." in f.filename else "")
    if ext not in ("pdf", "doc", "docx", "pptx", "xlsx", "txt", "csv"):
        return _json_ak.dumps({"ok": False, "error": "Dozwolone: pdf, doc, docx, pptx, xlsx, txt, csv"}), 400
    upload_dir = _os_ak.path.join("static", "uploads", "akademia", "files")
    _os_ak.makedirs(upload_dir, exist_ok=True)
    orig_name = f.filename.rsplit("/", 1)[-1].rsplit("\\", 1)[-1]
    fname = _uuid_ak.uuid4().hex[:12] + "." + ext
    save_path = _os_ak.path.join(upload_dir, fname)
    f.save(save_path)
    size = _os_ak.path.getsize(save_path)
    return _json_ak.dumps({"ok": True, "url": "/static/uploads/akademia/files/" + fname,
                           "name": orig_name, "size": size})


# ── API: Zapisz pole lekcji ────────────────────────────────────────
@app.route("/akademia/api/lekcja/<int:lid>", methods=["POST"])
@login_required
def akademia_api_lekcja_save(lid):
    data = request.get_json() or {}
    field = data.get("field", "")
    value = data.get("value", "")
    allowed = {"title", "category", "content", "video_url", "duration_min", "images", "attachments"}
    if field not in allowed:
        return _json_ak.dumps({"ok": False, "error": "Niedozwolone pole"}), 400
    db = get_db(); cur = db.cursor()
    try:
        cur.execute(f"UPDATE player_lessons SET {field}=%s WHERE id=%s", (value, lid))
        db.commit(); cur.close()
        return _json_ak.dumps({"ok": True})
    except Exception as e:
        try: db.rollback()
        except: pass
        return _json_ak.dumps({"ok": False, "error": str(e)}), 500


# ── API: Dodaj pytanie ─────────────────────────────────────────────
@app.route("/akademia/api/q-add/<int:lid>", methods=["POST"])
@login_required
def akademia_api_q_add(lid):
    data = request.get_json() or {}
    db = get_db(); cur = db.cursor()
    try:
        cur.execute("""
            INSERT INTO player_quiz_questions
            (lesson_id, question, options_json, correct_idx, explanation, question_type, order_num)
            VALUES (%s,%s,%s,%s,%s,%s,
                (SELECT COALESCE(MAX(order_num),0)+1 FROM player_quiz_questions WHERE lesson_id=%s))
            RETURNING id
        """, (lid, data.get("question","?"), data.get("options_json","[]"),
              int(data.get("correct_idx",0)), data.get("explanation",""),
              data.get("question_type","abcd"), lid))
        row = cur.fetchone()
        db.commit(); cur.close()
        return _json_ak.dumps({"ok": True, "id": row["id"] if row else None})
    except Exception as e:
        try: db.rollback()
        except: pass
        return _json_ak.dumps({"ok": False, "error": str(e)}), 500


