# ── API: Zmień kolejność pytań ─────────────────────────────────────
@app.route("/akademia/api/q-reorder/<int:lid>", methods=["POST"])
@login_required
def akademia_api_q_reorder(lid):
    data = request.get_json() or {}
    ids = data.get("ids", [])
    db = get_db(); cur = db.cursor()
    try:
        for i, qid in enumerate(ids):
            cur.execute("UPDATE player_quiz_questions SET order_num=%s WHERE id=%s AND lesson_id=%s",
                        (i, qid, lid))
        db.commit(); cur.close()
        return _json_ak.dumps({"ok": True})
    except Exception as e:
        try: db.rollback()
        except: pass
        return _json_ak.dumps({"ok": False, "error": str(e)}), 500


