# ── API: Dezaktywuj wszystkie pytania ────────────────────────────────────
@app.route("/akademia/api/q-deactivate-all", methods=["POST"])
@login_required
def akademia_api_q_deactivate_all():
    db = get_db(); cur = db.cursor()
    try:
        cur.execute("UPDATE player_quiz_questions SET active=false")
        count = cur.rowcount
        db.commit(); cur.close()
        return _json_ak.dumps({"ok": True, "count": count})
    except Exception as e:
        try: db.rollback()
        except: pass
        return _json_ak.dumps({"ok": False, "error": str(e)}), 500


