@app.route("/klub/api/drill/add", methods=["POST"])
@login_required
def api_drill_add():
    d = request.get_json(force=True) or {}
    sid = int(d.get("session_id", 0))
    mins = int(d.get("min", 0)); intn = int(d.get("intensywnosc", 3))
    load = mins * intn
    db = get_db(); cur = db.cursor()
    try:
        cur.execute("""INSERT INTO training_drills (session_id,typ,akcent,cwiczenie,min,intensywnosc,side_a,side_b,load)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id""",
            (sid, d.get("typ",""), d.get("akcent",""), d.get("cwiczenie",""), mins, intn, d.get("side_a",""), d.get("side_b",""), load))
        new_id = cur.fetchone()["id"]; db.commit()
        return jsonify({"ok": True, "id": new_id, "load": load})
    except Exception as e:
        db.rollback(); return jsonify({"ok": False, "error": str(e)})
    finally:
        cur.close()


