        cur.execute("""INSERT INTO training_period_plan (team_id,miesiac,plan_sesji) VALUES (%s,%s,%s)
            ON CONFLICT (team_id,miesiac) DO UPDATE SET plan_sesji=%s""", (team_id, miesiac, plan, plan))
