@app.route("/klub/api/termin/save", methods=["POST"])
@login_required
def api_termin_save():
    d = request.get_json(force=True) or {}
    team_id = int(d.get("team_id") or 0)
    data_str = (d.get("data") or "").strip()
    if not team_id or not data_str:
        return jsonify({"ok": False, "error": "Brak drużyny lub daty"})
    db = get_db(); cur = db.cursor()
    try:
        cur.execute("""INSERT INTO measurement_sessions (team_id, data, opis)
                       VALUES (%s,%s,%s)
                       ON CONFLICT (team_id, data) DO UPDATE SET opis=EXCLUDED.opis
                       RETURNING id""", (team_id, data_str, (d.get("opis") or "").strip()))
        r = cur.fetchone(); db.commit()
        return jsonify({"ok": True, "id": r["id"] if r else None})
    except Exception as e:
        db.rollback(); return jsonify({"ok": False, "error": str(e)})
    finally:
        cur.close()


