@app.route("/klub/api/pomiar/save", methods=["POST"])
@login_required
def api_pomiar_save():
    d = request.get_json(force=True) or {}
    try:
        sid = int(d.get("session_id") or 0)
        pid = int(d.get("person_id") or 0)
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "Zły identyfikator"})
    kod = (d.get("kod") or "").strip()
    if not sid or not pid or not kod:
        return jsonify({"ok": False, "error": "Brak danych"})
    w = d.get("wartosc")
    db = get_db(); cur = db.cursor()
    try:
        if w is None or w == "":
            # puste pole = skasowanie pomiaru, nie zapis zera
            cur.execute("""DELETE FROM measurements
                           WHERE session_id=%s AND person_id=%s AND kod=%s""", (sid, pid, kod))
        else:
            cur.execute("""INSERT INTO measurements (session_id, person_id, kod, wartosc)
                           VALUES (%s,%s,%s,%s)
                           ON CONFLICT (session_id, person_id, kod)
                           DO UPDATE SET wartosc=EXCLUDED.wartosc""", (sid, pid, kod, float(w)))
        db.commit(); return jsonify({"ok": True})
    except Exception as e:
        db.rollback(); return jsonify({"ok": False, "error": str(e)})
    finally:
        cur.close()


@app.route("/klub/api/catalog/save", methods=["POST"])
@login_required
def api_catalog_save():
    d = request.get_json(force=True) or {}
    team_id = int(d.get("team_id", 0)); typ = d.get("typ",""); akcent = d.get("akcent","").strip()
    if not akcent: return jsonify({"ok": False, "error": "Brak akcentu"})
    # Podany numer = edycja istniejącego wpisu, brak = dodanie nowego.
    try:    cat_id = int(d.get("id") or 0)
    except (TypeError, ValueError): cat_id = 0
    db = get_db(); cur = db.cursor()
    try:
        if cat_id:
            cur.execute("""UPDATE training_catalog
                           SET typ=%s, akcent=%s, side_a=%s, side_b=%s
                           WHERE id=%s AND team_id=%s RETURNING id""",
                        (typ, akcent, d.get("side_a",""), d.get("side_b",""), cat_id, team_id))
            r = cur.fetchone()
            if not r:
                db.rollback()
                return jsonify({"ok": False, "error": "Nie znaleziono wpisu do edycji"})
        else:
            cur.execute("""INSERT INTO training_catalog (team_id,typ,akcent,side_a,side_b)
                VALUES (%s,%s,%s,%s,%s) ON CONFLICT DO NOTHING RETURNING id""",
                (team_id, typ, akcent, d.get("side_a",""), d.get("side_b","")))
            r = cur.fetchone()
            if not r:
                db.rollback()
                return jsonify({"ok": False, "error": f"Akcent „{akcent}” już jest w katalogu"})
        db.commit()
        return jsonify({"ok": True, "id": r["id"] if r else None})
    except Exception as e:
        db.rollback(); return jsonify({"ok": False, "error": str(e)})
    finally:
        cur.close()


@app.route("/klub/api/catalog/del/<int:cat_id>", methods=["POST"])
@login_required
def api_catalog_del(cat_id):
    db = get_db(); cur = db.cursor()
    cur.execute("DELETE FROM training_catalog WHERE id=%s", (cat_id,))
    db.commit(); cur.close(); return jsonify({"ok": True})
